    'framework_2b522c10efd9' => ':where erbt über `:value2`, das die Benutzermenge `:value3` enthält. Eine zur Vererbung verwendete Relation darf nur Typen wie `[folder]` auflisten.',
    'framework_2d3082a46a0b' => 'Verzeichnissynchronisierung mit :value1 fehlgeschlagen: Ein SCIM-Verzeichnis besitzt keine Anbieter-Zugangsdaten. Erneuern Sie stattdessen sein Bearer-Token.',
    'framework_361167f5d601' => 'Die Auflösung hat mehr als :limit Relationsebenen durchlaufen. Verringern Sie die Verschachtelung oder erhöhen Sie cbox-id.fga.max_depth.',
