    'framework_4a882cbbcad9' => 'Client [:clientId] authentifiziert sich mit eigenen Schlüsseln (private_key_jwt) und hat kein Geheimnis. Erneuern Sie stattdessen den Schlüssel in seinem JWK Set.',
