    'framework_659b8670df25' => 'Verzeichnissynchronisierung mit :value1 fehlgeschlagen: Die Antwort ist kein JSON-Bericht (Report_Entry fehlt). Prüfen Sie, ob der Bericht als Webdienst aktiviert ist.',
    'framework_7987d4a55127' => '`:id` ist keine gültige ID: Erlaubt sind 1–128 druckbare Zeichen ohne Leerzeichen, `#` oder `@`. Ein einzelnes `*` ist reserviert.',
