    'framework_8038ba872fa4' => 'Der Scope [:key] ist kein gültiger Scope-Wert (RFC 6749 §3.3: druckbare ASCII-Zeichen, keine Leerzeichen, Anführungszeichen oder Backslashes, höchstens 128 Zeichen).',
    'framework_8aacc62aa689' => '`:value1` ist kein gültiger Relationsname. Verwenden Sie Kleinbuchstaben, Ziffern, `_` und `-`, beginnend mit einem Buchstaben.',
