    'framework_a4b74378dc23' => '`:value1` auf `:value2` wird aus anderen Relationen berechnet. Daher können keine Tupel dafür geschrieben werden. Schreiben Sie stattdessen die zugrunde liegenden Relationen.',
    'framework_aeb6433c3c63' => '`:value1` auf `:value2` zieht `:target` ab, das von `:self` selbst abhängt. Ein Ausschluss darf nicht auf die Relation zurückverweisen, die er bestimmt.',
