    'framework_c5f8b53abdbe' => 'Ungültige Assertion: Das Apple-Client-Geheimnis konnte nicht signiert werden. Prüfen Sie, ob der .p8-Schlüssel vollständig mit BEGIN- und END-Zeilen eingefügt wurde: :value1',
