    'this_role_grants_no_permissions_the_application_that_de_59b043d0' => 'Diese Rolle gewährt keine Berechtigungen. Die Anwendung, die sie definiert, bestimmt ihre Wirkung.',
    'this_role_is_declared_by_an_application_which_is_its_so_03e7843e' => 'Diese Rolle wird von einer Anwendung definiert, die ihre maßgebliche Quelle ist. Sie kann hier nicht bearbeitet werden.',
    'this_rule_binds_every_organization_here_choose_one_in_t_9d1bbde3' => 'Diese Regel gilt für alle Organisationen hier. Wählen Sie eine Organisation im Konsolenkopf, um deren Zuweisungen zu prüfen.',
    'this_rule_binds_every_organization_in_the_environment_i_91928f48' => 'Diese Regel gilt für alle Organisationen der Umgebung. Sie wird hier angezeigt, weil sie auch Ihre Organisation einschränkt. Ihr Betreiber verwaltet sie.',
    'this_user_is_held_at_a_password_change_they_cannot_reac_ce196382' => 'Dieser Benutzer muss zuerst sein Passwort ändern. Bis zum Austausch des von Ihnen vergebenen Passworts erhält er keinen weiteren Zugang.',
    'to_register_an_api_for_one_organization_find_it_here_it_48b04329' => 'Um eine API für eine Organisation zu registrieren, suchen Sie die Organisation hier. Sie wird dann oben als Eigentümer angeboten.',
    'user_erased_their_account_is_pseudonymised_and_the_eras_51e1f69a' => 'Benutzer gelöscht. Das Konto wurde pseudonymisiert und die Löschung als user.erased im Audit-Protokoll erfasst.',
    'valid_once_and_short_lived_turn_this_off_only_if_you_ar_521114e3' => 'Einmal und nur kurz gültig. Deaktivieren Sie dies nur, wenn Sie das Konto im Voraus anlegen und den Link selbst senden möchten.',
    'verify_that_authnrequests_really_come_from_this_applica_f3c58c70' => 'Prüfen, ob AuthnRequests tatsächlich von dieser Anwendung stammen, anhand ihres eigenen Signaturzertifikats.',
    'verify_the_domain_before_turning_capture_on_until_then_4ff9f310' => 'Verifizieren Sie die Domain vor der Aktivierung der SSO-Weiterleitung. Bis dahin hat die Organisation ihre Kontrolle über diese Adressen nicht nachgewiesen.',
    'verify_the_email_domains_you_own_so_your_people_are_rou_3f6d7cfe' => 'Verifizieren Sie Ihre E-Mail-Domains, damit Ihre Benutzer automatisch zu Ihrem Anbieter weitergeleitet werden.',
    'verify_the_signature_on_every_call_and_answer_within_th_5219ed81' => 'Prüfen Sie bei jedem Aufruf die Signatur und antworten Sie innerhalb des Zeitlimits. Währenddessen wartet eine Person auf dem Anmeldebildschirm.',
    'we_could_not_send_that_invitation_the_mail_server_refus_81a3f4df' => 'Die Einladung konnte nicht gesendet werden, da der Mailserver sie abgelehnt hat. Es wurde nichts erstellt. Versuchen Sie es erneut oder prüfen Sie die E-Mail-Konfiguration.',
    'webhook_id_webhook_timestamp_and_webhook_signature_with_73e511b0' => 'webhook-id, webhook-timestamp und webhook-signature mit einem whsec_-Geheimnis, prüfbar mit jeder Standard-Webhooks-Bibliothek.',
    'what_people_can_do_inside_your_apps_you_assign_roles_he_c31f1a20' => 'Was Personen in Ihren Apps tun dürfen. Sie weisen hier Rollen zu; jede App bestimmt, wozu ihre Rollen berechtigen.',
    'what_this_round_is_called_when_somebody_asks_which_revi_6e0713c0' => 'Der Name dieser Runde, wenn jemand wissen möchte, aus welcher Überprüfung eine Entscheidung stammt, etwa ein Quartal, Audit oder Datum.',
    'whatever_the_holder_has_wired_this_key_into_stops_worki_789a1199' => 'Alles, wofür der Inhaber diesen Schlüssel verwendet, funktioniert sofort nicht mehr. Dies lässt sich nicht rückgängig machen.',
    'whatever_the_holder_has_wired_this_key_into_stops_worki_e14495d2' => 'Alle Integrationen, in denen der Inhaber diesen Schlüssel verwendet, funktionieren sofort nicht mehr. Informieren Sie ihn möglichst vorher. Dies kann nicht rückgängig gemacht werden.',
    'when_an_app_or_agent_needs_your_go_ahead_to_act_as_you_3a85a2a9' => 'Wenn eine App oder ein Agent Ihre Zustimmung benötigt, um in Ihrem Namen zu handeln, erscheint die Anfrage hier. Genehmigen Sie nur selbst gestartete Anfragen.',
    'when_somebody_creates_an_api_key_for_one_of_your_apps_i_15c6370c' => 'Wenn jemand einen API-Schlüssel für eine Ihrer Apps erstellt, erscheint er hier mit Inhaber und Berechtigungen.',
    'whether_the_background_work_of_this_install_webhooks_si_0647da12' => 'Ob Hintergrundaufgaben dieser Installation tatsächlich versendet werden: Webhooks, Abmeldemitteilungen an verbundene Apps und E-Mails aus der Warteschlange.',
    'which_headers_every_delivery_carries_changing_it_issues_5a2ff32e' => 'Welche Header jede Zustellung enthält. Die Änderung erzeugt kein neues Geheimnis; Ihr bestehendes Geheimnis signiert in beiden Fällen.',
    'who_belongs_to_this_organization_and_what_they_can_do_s_330bf97e' => 'Wer dieser Organisation angehört und was die Personen tun dürfen. Wer noch kein Konto hat, wird per E-Mail eingeladen.',
    'who_gets_the_flag_when_no_rule_names_them_leave_it_off_b44a0c73' => 'Wer das Flag erhält, wenn keine Regel die Person nennt. Lassen Sie es aus, um eine Funktion zunächst für bestimmte Organisationen oder einen Prozentsatz auszurollen.',
    'who_is_signed_in_as_them_right_now_why_a_sign_in_was_al_181f0520' => 'Wer aktuell als diese Person angemeldet ist. Warum eine Anmeldung erlaubt, zusätzlich geprüft oder blockiert wurde, sehen Sie in Radar.',
    'whose_people_sign_in_through_it_its_domains_and_admin_p_9c461a3e' => 'Die Organisation, deren Benutzer sich darüber anmelden. Ihre Domains und der Admin-Portal-Link befinden sich auf der Organisationsseite.',
    'withdrawn_people_already_migrated_are_unaffected_anyone_228f7b22' => 'Zurückgezogen. Bereits migrierte Benutzer sind nicht betroffen; Benutzer des alten Systems können sich nicht mehr anmelden.',
    'workspace_suspended_its_members_can_no_longer_sign_in_a_82d7790e' => 'Arbeitsbereich gesperrt. Seine Mitglieder können sich nicht mehr anmelden, und seine Umgebungen verarbeiten keine Authentifizierung mehr.',
    'write_reorder_and_delete_radar_rules_tune_the_built_in_254f1eff' => 'Radar-Regeln erstellen, sortieren und löschen, integrierte Regeln anpassen sowie Einträge zu Zulassungs- und Sperrlisten hinzufügen oder daraus entfernen.',
    'you_are_the_only_owner_transfer_ownership_to_someone_el_1e7b6195' => 'Sie sind der einzige Eigentümer. Übertragen Sie zuerst die Eigentümerschaft an eine andere Person, oder löschen Sie die Organisation.',
    'you_can_set_this_back_to_prefer_sso_or_both_available_a_b84203a4' => 'Sie können jederzeit zu „SSO bevorzugen“ oder „Beides verfügbar“ zurückkehren. Bereits beendete Sitzungen bleiben beendet.',
    'you_lose_access_to_this_organization_and_its_apps_immed_47fdba25' => 'Sie verlieren sofort den Zugang zu dieser Organisation und ihren Apps. Ein Administrator kann Sie erneut einladen.',
    'you_need_credentials_from_your_own_account_with_the_pro_6556573b' => 'Sie benötigen Zugangsdaten Ihres eigenen Kontos beim Anbieter, meist eine Client-ID und ein Geheimnis. Apple stellt stattdessen einen Signaturschlüssel aus.',
    'your_authentication_policy_still_applies_password_stren_84825ce9' => 'Ihre Authentifizierungsrichtlinie gilt weiterhin: Passwortstärke, Prüfung auf Datenlecks, E-Mail-Bestätigung, Ratenlimits und Bot-Prüfungen.',
    'your_endpoint_is_called_in_the_middle_of_an_operation_a_ab67a6b0' => 'Ihr Endpunkt wird während eines Vorgangs aufgerufen, und seine Antwort beeinflusst das Ergebnis, etwa durch zusätzliche Token-Daten oder die Ablehnung einer Anmeldung.',
    'your_endpoints_get_a_signed_message_after_something_hap_04723db4' => 'Ihre Endpunkte erhalten nach Ereignissen hier eine signierte Nachricht, damit Ihre Systeme reagieren können, ohne uns ständig abzufragen.',
    'your_hr_system_people_get_an_account_on_their_start_dat_6be42da6' => 'Ihr HR-System: Personen erhalten am ersten Arbeitstag ein Konto und verlieren den Zugang nach ihrem letzten Arbeitstag.',
    'your_organization_s_name_domains_and_defaults_changes_h_8e3220c0' => 'Name, Domains und Standardeinstellungen Ihrer Organisation. Änderungen gelten für alle, die sich über diese Organisation anmelden.',
    'your_own_api_you_choose_scope_by_scope_which_of_its_sco_6f77f332' => 'Ihre eigene API. Sie entscheiden für jeden Scope, ob von Organisationen registrierte Apps ihn anfordern dürfen.',
    'your_own_credentials_with_each_provider_offered_on_ever_82ce1e08' => 'Ihre eigenen Zugangsdaten für jeden Anbieter, angeboten auf allen Anmeldeseiten dieser Umgebung. Jede Organisation übernimmt sie.',
    'your_own_credentials_with_each_provider_offered_to_ever_d1715d1a' => 'Ihre eigenen Zugangsdaten für jeden Anbieter, verfügbar für alle in dieser Umgebung. Jede Organisation übernimmt sie.',
    'your_receiver_keeps_the_same_secret_used_exactly_as_wri_431d83f5' => 'Ihr Empfänger behält dasselbe Geheimnis. Es wird unverändert einschließlich des whsec_-Präfixes als HMAC-Schlüssel für X-Cbox-Signature verwendet.',
    'your_sign_in_page_carries_your_logo_and_colours_people_76d3ce22' => 'Ihre Anmeldeseite trägt Ihr Logo und Ihre Farben. Da Benutzer hier ihr Passwort eingeben, soll sie als Ihre Seite erkennbar sein.',
    'your_workspace_its_projects_team_keys_and_billing_sign_d55c648f' => 'Ihr Arbeitsbereich mit Projekten, Team, Schlüsseln und Abrechnung. Die Anmeldung bei Ihren Apps wird in der jeweiligen Umgebungskonsole festgelegt.',
    'a_feature_flag_is_a_switch_your_apps_ask_about_for_one_9a43d208' => 'Ein Feature-Flag ist ein Schalter, dessen Wert Ihre Apps für eine Person in einer Organisation abfragen. Aktivieren Sie es für bestimmte Benutzer, Organisationen oder einen Prozentsatz aller Benutzer. Jede App erhält dieselbe Antwort über den Claim `feature_flags` im Token oder den Auswertungsendpunkt, ohne neue Bereitstellung. Benutzerregeln haben Vorrang vor Organisationsregeln, diese vor dem Rollout und dieser vor dem Standardwert.',
    'a_key_lets_your_own_scripts_and_integrations_call_an_ap_4edbc37d' => 'Mit einem Schlüssel können Ihre Skripte und Integrationen die API einer App ohne Anmeldung in Ihrem Namen aufrufen. Er hat höchstens Ihre Berechtigungen in dieser App. Werden Ihre Rechte eingeschränkt, verliert auch der Schlüssel diese Rechte. Er wird nur einmal angezeigt; kopieren Sie ihn bei der Erstellung und widerrufen Sie ihn sofort, wenn er offengelegt wurde oder nicht mehr verwendet wird.',
    'a_permission_is_one_thing_a_role_is_allowed_to_do_creat_522b0034' => 'Eine Berechtigung erlaubt einer Rolle eine bestimmte Aktion, etwa „Rechnungen erstellen“ oder „Berichte lesen“. Sie können hier ohne Code eigene Berechtigungen definieren und zu Rollen zusammenstellen. Apps können ihre Berechtigungen auch automatisch registrieren, damit die Liste mit der tatsächlichen Prüfung übereinstimmt. Eigene Berechtigungen können Sie bearbeiten; von der Umgebung bereitgestellte dürfen Sie verwenden, aber nicht ändern.',
    'a_phone_with_the_authenticator_app_installed_becomes_th_caef4b54' => 'Ein Smartphone mit installierter Authenticator-App beantwortet Genehmigungsanfragen und meldet Anmeldungen unter Ihrem Konto. Registrieren Sie es einmal durch Scannen des Codes. Entfernen Sie es hier sofort bei Verlust; danach kann es nichts mehr genehmigen.',
    'a_project_is_one_idp_product_this_workspace_owns_and_it_a5e40dff' => 'Ein Projekt ist ein Identitätsanbieter-Produkt dieses Arbeitsbereichs und enthält dessen Umgebungen. Solange der Arbeitsbereich in seiner eigenen Konsole kein Projekt erstellt hat, gibt es hier nichts auszuwählen oder zu öffnen. Auf dieser Seite lässt sich kein Projekt im Namen des Arbeitsbereichs erstellen.',
    'a_project_is_one_of_your_products_with_its_own_plan_sig_45d566d1' => 'Ein Projekt ist eines Ihrer Produkte mit eigenem Tarif, eigener Anmeldung und Umgebungen wie Produktion und Staging. Öffnen Sie hier eine Umgebung zur Verwaltung. Erstellen Sie ein neues Projekt, wenn ein Produkt eigenständig betrieben und abgerechnet werden soll.',
    'a_role_is_a_job_title_your_apps_understand_editor_suppo_73cd7eac' => 'Eine Rolle ist eine Aufgabenbezeichnung, die Ihre Apps verstehen, etwa „Redakteur“ oder „Supportmitarbeiter“. Sie legen hier fest, wer welche Rolle erhält. Jede App bestimmt selbst die Berechtigungen ihrer Rollen. Die Rollen begleiten eine Person in alle verbundenen Apps, sodass Sie den Zugriff zentral gewähren und entziehen können.',
    'a_round_where_you_go_through_who_holds_which_role_and_c_617023b9' => 'In einer Zugriffsüberprüfung prüfen Sie, wer welche Rolle besitzt und weiterhin benötigt. Rechte sammeln sich oft unbemerkt an, etwa wenn Personen das Team wechseln und alte Berechtigungen behalten. Eine Überprüfung hilft beim Aufräumen. Widerrufe werden beim Abschluss angewendet, und der gesamte Vorgang wird für Ihre Prüfer dokumentiert.',
    'a_schema_says_what_an_action_s_events_must_look_like_wh_d27be344' => 'Ein Schema legt fest, wie Ereignisse einer Aktion aussehen müssen: welche Zieltypen sie nennen und welche Metadaten sie enthalten. Ereignisse mit Schema werden beim Eingang geprüft. Ohne Schema werden sie unverändert akzeptiert, sofern der strenge Modus nicht aktiviert ist.',
    'a_workspace_is_one_signed_up_company_s_home_on_this_ins_3053f712' => 'Ein Arbeitsbereich ist der Bereich eines registrierten Unternehmens in dieser Installation und enthält dessen Projekte, Umgebungen und Team. Öffnen Sie ihn, um Produkte und Umgebungen zu verwalten. Eine Sperrung meldet die Mitglieder ab und stoppt die Anmeldung in allen zugehörigen Umgebungen.',
    'access_accumulates_people_change_teams_and_keep_what_th_cd6b423c' => 'Zugriffsrechte sammeln sich an. Personen wechseln das Team, behalten aber alte Rechte, bis es bei einem Audit auffällt. Eine Überprüfung erfasst die aktuellen Zuweisungen und verlangt für jede einzelne eine Entscheidung, ob sie noch benötigt wird.',
    'add_them_to_one_below_to_grant_access_inside_it_or_if_y_386e5f3c' => 'Fügen Sie die Person unten einer Organisation hinzu, um ihr dort Zugriff zu gewähren. Falls Ihre Apps keine eigenen Mandanten verwenden, können Sie stattdessen eine Administrations- und Supportrolle für die gesamte Umgebung vergeben.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_4b6ac4cb' => 'Eine Administrations- und Supportrolle vergeben Sie an eigene Mitarbeiter, etwa Support oder Betrieb, für die gesamte Umgebung. Sie gilt in jeder Organisation und kann von deren Administratoren weder gesehen noch vergeben oder entfernt werden. Eine auf diesem Weg vergebene App-Rolle gilt weiterhin nur für die betreffende App.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_caea5beb' => 'Eine Administrations- und Supportrolle vergeben Sie an eigene Mitarbeiter für die gesamte Umgebung. Sie gilt in jeder Organisation und kann von deren Administratoren weder gesehen noch geändert werden.',
    'an_agent_is_any_software_that_acts_on_this_environment_05aebde2' => 'Ein Agent ist Software, die mit einem Verwaltungsschlüssel in dieser Umgebung handelt: ein KI-Assistent wie Claude Code oder Cursor, ein interner Bot oder Ihr Backend. Geben Sie jedem Agenten einen eigenen Schlüssel mit den nötigen Scopes. Legen Sie fest, welche Aktionen Ihre Genehmigung benötigen, und widerrufen Sie den Schlüssel nach Abschluss oder bei verdächtigem Verhalten sofort.',
    'an_api_is_a_service_of_yours_that_receives_access_token_2747c516' => 'Eine API ist ein Dienst von Ihnen, der Zugriffstokens empfängt, etwa https://api.example.com. Registrieren Sie sie mit den unterstützten Scopes. Sie entscheiden dann, welche Scopes Apps der Organisationen hier anfordern dürfen. Ein Token für die API enthält deren Adresse als Zielgruppe, die Ihr Dienst prüft.',
    'an_environment_is_a_fully_isolated_identity_service_wit_fed9a3d8' => 'Eine Umgebung ist ein vollständig isolierter Identitätsdienst mit eigenen Benutzern, Schlüsseln, Anmeldung und Aussteller. Hier sehen Sie alle Umgebungen dieser Installation mit ihrem Arbeitsbereich. Erstellen Sie eine Umgebung, wählen Sie sie in der Konsole aus und richten Sie ihre erste Organisation samt Administrator ein.',
    'an_environment_is_fully_isolated_its_own_users_keys_sig_bc49f6f9' => 'Eine Umgebung ist vollständig isoliert und besitzt eigene Benutzer, Schlüssel, Anmeldung und Aussteller. Erstellen Sie oben Ihre erste Umgebung und richten Sie anschließend eine Organisation mit Administrator ein.',
    'an_identity_provider_that_imports_service_provider_meta_9cbb9457' => 'Ein Identitätsanbieter, der Dienstanbieter-Metadaten importiert, verwendet diese URL statt einzelner Angaben für Entity-ID und ACS-URL. Sie funktioniert bereits, bevor die Angaben des Identitätsanbieters vervollständigt sind.',
    'an_organization_is_where_users_sign_in_methods_and_role_ae379847' => 'Eine Organisation umfasst Benutzer, Anmeldemethoden und Rollen. Erstellen Sie oben eine Organisation oder richten Sie unter „Umgebungen“ die erste Organisation mit Administrator für die Umgebung ein.',
    'an_organization_s_own_provider_replaces_the_environment_5a3f34fa' => 'Ein eigener Anbieter einer Organisation ersetzt auf ihrer Anmeldeseite den Anbieter der Umgebung. Auch deaktivierte übernommene Anbieter werden aufgelistet. Ihre Deaktivierung entfernt nur die Schaltfläche; erst die SSO-Pflicht verhindert andere Anmeldewege.',
    'api_keys_and_tokens_your_apps_and_agents_need_for_other_f9b71876' => 'API-Schlüssel und Tokens für externe Dienste, die Ihre Apps und Agenten benötigen, werden hier zentral verschlüsselt gespeichert. Hinterlegen Sie ein Geheimnis einmal und gewähren Sie ausgewählten Apps die Nutzung. Es wird danach nicht erneut angezeigt; erneuern Sie es bei Verlust.',
    'api_keys_your_apps_and_agents_present_to_other_services_ab18c348' => 'API-Schlüssel, die Ihre Apps und Agenten bei anderen Diensten verwenden. Jeder Wert wird verschlüsselt gespeichert, nur ausdrücklich berechtigten Apps übergeben und nach der Speicherung nicht mehr angezeigt.',
    'apps_asking_to_act_on_one_of_your_users_behalf_each_use_4583b737' => 'Apps, die im Namen eines Ihrer Benutzer handeln möchten. Jeder Benutzer genehmigt seine eigenen Anfragen. Lehnen Sie hier nur Anfragen ab, die nach Missbrauch aussehen; die Ablehnung wird im Audit-Protokoll erfasst.',
    'apps_that_keep_their_own_user_list_drift_out_of_step_th_fc8e8671' => 'Apps mit eigenen Benutzerlisten verlieren bei Ein- und Austritten schnell den aktuellen Stand. Eine SCIM-Verbindung überträgt jede Änderung sofort, einschließlich der Austritte, die sonst leicht übersehen werden.',
    'cbox_id_posts_a_signed_message_to_your_endpoint_after_s_8dadac57' => 'Cbox ID sendet nach Ereignissen wie einem neuen Mitglied oder einer Rollenänderung eine signierte Nachricht an Ihren Endpunkt. So reagieren Ihre Systeme ohne ständige Abfragen. Zustellungen werden wiederholt. Der Endpunkt wird nachträglich informiert und kann den Vorgang nicht beeinflussen.',
    'certify_what_is_still_needed_revoke_what_is_not_nothing_31e57691' => 'Bestätigen Sie weiterhin benötigte Rechte und widerrufen Sie die übrigen. Nichts wird vor Abschluss der Überprüfung angewendet. Eine widerrufene Administrations- und Supportrolle wird dann in allen Organisationen gleichzeitig entfernt.',
    'choose_scim_if_your_provider_pushes_to_us_google_worksp_99b715bb' => 'Wählen Sie SCIM, wenn Ihr Anbieter Daten an uns sendet, Google Workspace oder Entra, wenn wir sie abrufen sollen, oder Ihr HR-System wie Workday, BambooHR, Rippling, HiBob oder Personio, damit Benutzer am ersten Arbeitstag angelegt werden.',
    'claude_code_opens_your_browser_to_sign_in_here_and_asks_a86b6b5e' => 'Claude Code öffnet Ihren Browser zur Anmeldung und fragt, was Sie erlauben möchten. Es muss kein Schlüssel verwahrt werden. Jeder MCP-Client mit OAuth-Anmeldung funktioniert mit dieser URL auf dieselbe Weise.',
    'comma_or_space_separated_a_scope_you_type_is_unowned_it_c5513416' => 'Durch Komma oder Leerzeichen getrennt. Ein eingegebener Scope hat keinen API-Eigentümer. Er wird unverändert in die Tokens dieser App übernommen, kann aber nie die Zielgruppe einer registrierten API festlegen. Verwenden Sie dafür die Listen oben.',
    'create_change_enable_disable_and_delete_sso_connections_58aa8cd7' => 'SSO-Verbindungen erstellen, ändern, aktivieren, deaktivieren und löschen, SSO für eine Organisation vorschreiben sowie ihre E-Mail-Domains verifizieren und zur SSO-Weiterleitung verwenden. Ändert die Anmeldung der Benutzer.',
    'creates_the_organization_its_owner_its_first_product_an_79cca112' => 'Erstellt die Organisation, ihren Eigentümer, ihr erstes Produkt und dessen Produktionsumgebung. Der Eigentümer erhält per E-Mail einen Link zum Festlegen seines Passworts. Sie vergeben kein Passwort für ihn.',
    'define_replace_and_delete_the_schemas_audit_events_are_c37e0366' => 'Schemas zur Prüfung von Audit-Ereignissen definieren, ersetzen und löschen sowie deren Aufbewahrungsdauer ändern. Eine kürzere Aufbewahrung löscht ältere Ereignisse endgültig.',
    'deleting_this_workspace_tears_down_every_project_and_en_f26b2e2f' => 'Beim Löschen dieses Arbeitsbereichs werden alle zugehörigen Projekte und Umgebungen entfernt. Zum Schutz aktiver Identitätsanbieter ist dies nicht im Self-Service möglich. Wenden Sie sich an den Support.',
    'each_organization_is_a_company_or_team_using_your_produ_08cdcb7d' => 'Jede Organisation ist ein Unternehmen oder Team, das Ihr Produkt nutzt, mit eigenen Mitgliedern, Rollen, Domains und SSO. Erstellen Sie eine Organisation pro registriertem Unternehmen. Öffnen Sie sie, um Mitglieder, Einladungen und verifizierte Domains zu verwalten oder sie zu sperren.',
    'each_pipe_lets_people_connect_their_own_account_at_a_se_ec4853ae' => 'Jede Pipeline ermöglicht Benutzern, ihr eigenes Konto bei Diensten wie GitHub, Google oder Slack zu verbinden. Die Tokens werden hier verschlüsselt gespeichert und aktuell gehalten. Berechtigte Apps fordern beim Zugriff im Namen der Person ein gültiges Token an und speichern selbst keines.',
    'each_project_in_your_workspace_has_its_own_plan_and_env_c5ff35b1' => 'Jedes Projekt Ihres Arbeitsbereichs hat einen eigenen Tarif und ein Umgebungskontingent. Hier sehen Sie beides neben der Monatsnutzung: Organisationen, kostenpflichtige SSO-Verbindungen und Anmeldungen. Die Abrechnung berücksichtigt monatlich aktive Benutzer und Unternehmensverbindungen wie SSO und SCIM. Für Sandbox-Umgebungen fallen keine Verbindungsgebühren an.',
    'environment_wide_anyone_with_an_account_in_this_environ_c60d926c' => 'Umgebungsweit: Alle Benutzer mit einem Konto in dieser Umgebung können sich bei der Anwendung anmelden, unabhängig von ihrer Organisation. Wählen Sie eine Organisation, wenn dies nicht beabsichtigt ist.',
    'erase_a_person_for_good_gdpr_art_17_their_credentials_s_ff46c230' => 'Eine Person dauerhaft löschen (DSGVO Art. 17): Zugangsdaten, Sitzungen, Mitgliedschaften und personenbezogene Daten werden gelöscht, das Konto wird pseudonymisiert. Dies lässt sich nicht rückgängig machen.',
    'evaluated_in_order_the_deny_list_the_allow_list_your_ru_00db2fea' => 'Prüfreihenfolge: Sperrliste, Zulassungsliste, Ihre Regeln von oben nach unten mit Entscheidung durch den ersten Treffer, danach die integrierten Regeln mit Entscheidung durch die strengste zutreffende Regel. Ohne Treffer wird der Zugriff erlaubt.',
    'every_action_is_accepted_as_your_app_sends_it_add_a_sch_fce48faa' => 'Jede Aktion wird so akzeptiert, wie Ihre App sie sendet. Fügen Sie ein Schema hinzu, um ihre Ereignisse beim Eingang zu prüfen. Die Konsistenz des Protokolls wird beim Schreiben eines Ereignisses sichergestellt, nicht erst beim Lesen.',
    'every_administrative_change_members_roles_connections_a_ef641619' => 'Jede administrative Änderung an Mitgliedern, Rollen, Verbindungen oder Apps wird hier sofort mit ausführender Person und Zeitpunkt erfasst. Dafür ist keine Einrichtung erforderlich.',
    'every_api_key_sitting_in_an_app_s_config_or_environment_975161a8' => 'API-Schlüssel in App-Konfigurationen oder Umgebungsdateien lassen sich nicht zentral erneuern oder schnell entziehen. Hier werden sie verschlüsselt gespeichert, pro App freigegeben und mit einem Klick widerrufen.',
    'every_api_key_the_people_in_this_organization_have_crea_15e73625' => 'Alle API-Schlüssel, die Personen dieser Organisation für ihre Apps erstellt haben. Widerrufen Sie offengelegte oder ungenutzte Schlüssel. Benutzer erstellen ihre eigenen Schlüssel unter „Mein Konto“.',
    'every_api_key_the_people_in_this_organization_have_crea_fe7787a7' => 'Alle API-Schlüssel, die Personen dieser Organisation für ihre Apps erstellt haben: Inhaber, App, Berechtigungen und letzte Verwendung. Ein Schlüssel hat höchstens die Rechte seines Inhabers und funktioniert nach dessen Austritt nicht mehr. Widerrufen Sie offengelegte oder ungenutzte Schlüssel. Benutzer erstellen ihre eigenen Schlüssel unter „Mein Konto“.',
    'every_app_that_signs_people_in_through_cbox_id_or_calls_1e151c65' => 'Jede App, die Benutzer über Cbox ID anmeldet oder dessen API aufruft, wird hier registriert und erhält eigene Zugangsdaten. Registrieren Sie jeweils eine App pro Anwendung und Umgebung. Teilen Sie keine Zugangsdaten, damit ein Widerruf die anderen Apps nicht beeinträchtigt.',
    'every_browser_and_device_signed_in_as_you_the_apps_you_ee516093' => 'Alle Browser und Geräte, auf denen Sie angemeldet sind, autorisierte Apps sowie Ihre letzten Anmeldungen und Sicherheitsänderungen. Wenn Ihnen etwas unbekannt ist, melden Sie die Sitzung ab oder widerrufen Sie den App-Zugriff und ändern Sie anschließend Ihr Passwort.',
    'every_change_made_in_this_organization_who_did_what_to_1d80a907' => 'Jede Änderung in dieser Organisation: wer was an welchem Objekt und wann getan hat. Die Einträge sind über Hashes verkettet; das Entfernen oder Ändern eines Eintrags unterbricht die Kette und wird sichtbar. Das Protokoll ist bewusst schreibgeschützt und dient als Nachweis für Prüfer.',
    'every_link_between_cbox_id_and_another_system_in_one_pl_0376dee4' => 'Alle Verbindungen zwischen Cbox ID und anderen Systemen an einem Ort: SSO, soziale Anmeldung, Verzeichnis- und HR-Synchronisierung, ausgehende Benutzerbereitstellung, SAML-Apps, Webhooks, Hooks, Log-Streams und Pipelines. Jede Katalogkarte öffnet die passende Einrichtung. Unter „Verbindungen“ sehen Sie alle bestehenden Verbindungen mit Status, fehlerhafte zuerst.',
    'every_organization_in_the_environment_the_console_is_po_0de4eff9' => 'Alle Organisationen der aktuell ausgewählten Umgebung als Hierarchie von Wiederverkäufern, verwalteten Organisationen und Untereinheiten. Erstellen oder sperren Sie eine Organisation oder verschieben Sie sie unter eine andere übergeordnete Organisation.',
    'every_page_you_open_from_now_on_organizations_usage_org_7ba726d3' => 'Alle ab jetzt geöffneten Seiten, etwa Organisationen, Nutzung oder Organisationsdetails, lesen die Daten dieser Umgebung statt der bisherigen. In keiner Umgebung wird etwas geändert.',
    'every_person_with_an_identity_in_this_environment_which_f9f26f27' => 'Alle Personen mit einer Identität in dieser Umgebung, unabhängig von ihren Organisationen. Öffnen Sie eine Person, um Passwort oder zweiten Faktor zurückzusetzen, Sitzungen abzumelden, sie zu deaktivieren, Organisationen und Rollen zu ändern oder sie aufgrund eines Löschantrags dauerhaft zu löschen.',
    'every_revoke_recorded_on_this_review_is_applied_for_rea_1abdd266' => 'Alle in dieser Überprüfung erfassten Widerrufe werden jetzt angewendet. Nicht geprüfte Einträge werden gemäß der Überprüfungsrichtlinie behandelt, die standardmäßig den Widerruf vorsieht. Dies lässt sich nicht rückgängig machen.',
    'every_secret_that_signs_this_app_in_right_now_only_a_ha_6aceec1d' => 'Alle derzeit für diese App gültigen Geheimnisse. Es wird jeweils nur ein Hash gespeichert. Die Liste zeigt die letzten vier Zeichen, damit Sie das Geheimnis einer Bereitstellung zuordnen können.',
    'every_token_it_issued_is_revoked_now_and_no_new_sign_in_e0dca49c' => 'Alle damit ausgestellten Tokens werden jetzt widerrufen, und neue Anmeldungen können es nicht mehr verwenden. Apps mit eigener Token-Prüfung akzeptieren Tokens noch bis zu deren Ablauf, spätestens jedoch bis zum Sitzungsende.',
    'every_way_a_person_can_sign_in_here_password_passkeys_m_1abc176e' => 'Alle Anmeldemethoden mit ihrem Status und dem Ort ihrer Einstellungen: Passwort, Passkeys, Anmeldelink, soziale Anmeldung, Enterprise SSO und zweiter Faktor. Die meisten legt diese Umgebung fest, SSO-Verbindungen die jeweilige Organisation. Einschränkungen durch die Bereitstellung werden mit dem zugehörigen Einstellungsnamen angezeigt.',
    'every_workspace_on_this_install_open_one_to_walk_its_pr_4abbea51' => 'Alle Arbeitsbereiche dieser Installation. Öffnen Sie einen, um Produkte und Umgebungen zu verwalten. Eine Sperrung meldet alle Mitglieder ab und stoppt die Authentifizierung in allen zugehörigen Umgebungen.',
    'everyone_who_administers_this_workspace_the_built_in_ro_26825e5f' => 'Alle Verwalter dieses Arbeitsbereichs mit ihrer integrierten Rolle (Eigentümer, Administrator, Entwickler, Mitglied oder Betrachter) und den zugänglichen Umgebungen. Laden Sie Personen per E-Mail ein und geben Sie ihnen nur die für ihre Arbeit nötigen Umgebungen frei.',
    'everyone_who_can_sign_in_to_this_organization_and_the_i_e278dd18' => 'Alle Personen, die sich bei dieser Organisation anmelden können, sowie Ihre noch nicht angenommenen Einladungen. Laden Sie Personen per E-Mail ein. Sie richten ihre Anmeldung selbst ein, sodass Sie keine fremden Passwörter verwalten müssen.',
