    'catalog_description' => 'Der App-Katalog ist die Liste, die Ihre Produkte in ihrer App-Auswahl anzeigen. Veröffentlichen Sie jede App mit Start-URL und Symbol und legen Sie fest, wer sie sehen kann. Anmeldung und Zugriff kontrolliert weiterhin die jeweilige App.',
