    '_part1_a_code_can_be_taken_by_a_sim_swap_or_number_port_690b2597' => ':part1 Ein Code kann durch SIM-Swapping oder die Übertragung Ihrer Rufnummer gestohlen, im Telefonnetz abgefangen oder auf einer täuschend echten Anmeldeseite eingegeben werden. Trotzdem ist er deutlich sicherer als ein Passwort allein. Aktivieren Sie ihn für Personen, die weder eine Authenticator-App noch einen Passkey nutzen können.',
    '_part1_a_logo_linked_from_another_site_told_that_site_a_dcac9b85' => ':part1 Ein von einer anderen Website eingebundenes Logo verriet dieser Website, wer Ihre Anmeldeseite öffnete. Deshalb zeigen gehostete Seiten jetzt nur hier hochgeladene Bilder. Laden Sie es unten unter :part2 hoch oder entfernen Sie es, um diesen Hinweis auszublenden.',
    '_part1_a_role_is_a_label_stamped_into_the_token_the_one_92a78021' => ':part1 Eine Rolle ist eine Bezeichnung im Token. Von einer App definierte Rollen können hier nur gelesen werden; die übrigen legen Sie selbst fest. Jedes Mitglied hat außerdem genau eine :part2 :part3 :part4 (Eigentümer, Administrator, Entwickler, Mitglied oder Betrachter), die festlegt, was es in dieser Konsole verwalten darf.',
    '_part1_already_belongs_to_another_api_in_this_environme_bab95da8' => '„:part1“ gehört bereits zu einer anderen API in dieser Umgebung. Eine Token-Anfrage benennt einen Berechtigungsbereich allein anhand seines Schlüssels. Daher kann jeder Schlüssel nur einer API gehören.',
    '_part1_belong_to_an_api_this_app_may_not_use_they_are_l_99264721' => ':part1 gehören zu einer API, die diese App nicht verwenden darf. Sie werden aus allen Tokens ausgeschlossen. Entfernen Sie sie aus den eingegebenen Berechtigungsbereichen.',
    '_part1_can_sign_in_with_passwords_or_with_this_connecti_ebadb8e1' => ':part1 können sich mit Passwörtern oder über diese Verbindung anmelden. Wenn Sie Single Sign-on vorschreiben, werden alle anderen Anmeldewege abgelehnt, sodass auch bereits ausgestellte Zugangsmittel den gerade eingerichteten Anbieter nicht umgehen können. Die meisten Unternehmen, die einen IdP anbinden, wünschen dieses Verhalten. Lesen Sie jedoch zuerst, was die Einstellung bewirkt.',
    '_part1_has_no_permissions_yet_so_part2_part3_arrives_em_a819e0c7' => ':part1 hat noch keine Berechtigungen, daher :part2 bleibt :part3 leer. Der Rollenname ist weiterhin vorhanden und kann ausgewertet werden.:part4',
    '_part1_is_already_set_up_for_this_organization_change_i_dea89857' => ':part1 ist für diese Organisation bereits eingerichtet. Ändern Sie die Zugangsdaten oder entfernen Sie die Verbindung zuerst.',
    '_part1_is_no_longer_offered_anyone_who_signed_in_with_i_b1a43020' => ':part1 wird nicht mehr angeboten. Alle, die sich darüber angemeldet haben, behalten ihr Konto und können weiterhin ihr Passwort verwenden.',
    '_part1_is_off_on_every_sign_in_page_its_credentials_are_2dc58cfc' => ':part1 ist auf allen Anmeldeseiten deaktiviert. Die Zugangsdaten bleiben gespeichert, sodass Sie die Verbindung wieder aktivieren können.',
    '_part1_is_off_on_this_organization_s_sign_in_page_its_c_5a7d1345' => ':part1 ist auf der Anmeldeseite dieser Organisation deaktiviert. Die Zugangsdaten bleiben gespeichert, sodass Sie die Verbindung wieder aktivieren können.',
    '_part1_is_your_only_way_to_sign_in_set_a_password_or_ad_968a0fd3' => ':part1 ist Ihre einzige Anmeldemöglichkeit. Legen Sie zuerst ein Passwort fest oder fügen Sie einen Passkey hinzu, bevor Sie die Verbindung trennen.',
    '_part1_is_your_organization_s_single_sign_on_it_is_how_a02887f1' => ':part1 ist die Single-Sign-on-Verbindung Ihrer Organisation. Darüber identifiziert Ihre Organisation Sie, deshalb kann die Verbindung hier nicht getrennt werden.',
    '_part1_its_team_is_administered_under_workspace_team_by_939d535a' => ':part1 Das Team wird unter Arbeitsbereich › Team von einer Person mit einer Arbeitsbereichsrolle verwaltet, nicht hier.',
    '_part1_part2_nothing_here_is_set_by_part3_yet_change_an_a8ead075' => ':part1 :part2 Noch wird hier nichts durch :part3 festgelegt. Sobald Sie unten etwas ändern, wird daraus eine eigene Regel dieser Organisation.',
    '_part1_part2_up_to_date_part3_deprovisioned_part4_part5_5604a19e' => ':part1 :part2 aktuell, :part3 deprovisioniert,:part4 :part5 übersprungen, :part6 Gruppen :part7.',
    '_part1_part2_update_your_receiver_first_from_the_next_a_d1d60a6e' => ':part1 :part2 Aktualisieren Sie zuerst Ihren Empfänger: Ab dem nächsten Versuch lehnt er jede Zustellung ab, die er nicht verifizieren kann.',
    '_part1_refuses_the_sign_in_unless_this_matches_exactly_8d9cdd26' => ':part1 lehnt die Anmeldung ab, wenn dieser Wert nicht exakt übereinstimmt. Er bleibt für diese Einrichtung gespeichert, sodass Sie ihn jetzt in :part2 einfügen und anschließend hier speichern können.',
    '_part1_sessions_passkeys_and_second_factors_identity_pr_1ab27bf9' => ':part1 – Sitzungen, Passkeys und zweite Faktoren, Profile bei Identitätsanbietern, Verzeichnisdaten, ausgestellte Tokens, Rollenzuweisungen und der Auditverlauf bleiben erhalten und können reaktiviert werden.',
