    'you_can_turn_it_off_again_on_part1_part2_sessions_that_89d71a9d' => 'Sie können dies unter :part1 :part2 wieder deaktivieren. Beendete Sitzungen bleiben beendet.',
    'you_hold_no_permissions_in_part1_so_a_key_would_identif_2c680207' => 'Sie haben in :part1 keine Berechtigungen. Ein Schlüssel würde Sie dort lediglich identifizieren.',
    'your_endpoint_verifies_the_part1_header_on_each_request_b7ca1bb8' => 'Ihr Endpunkt prüft mit diesem Geheimnis bei jeder Anfrage den Header :part1.',
    'your_roles_using_permission' => 'In :count Ihrer Rollen|In :count Ihrer Rollen',
    'everything_your_organization_has_set_up_and_what_is_lef_2eaad20f' => 'Alles, was Ihre Organisation bereits eingerichtet hat und was noch zu tun ist. Die Checkliste zeigt den tatsächlichen Einrichtungsstand. Jeder Schritt wird automatisch abgehakt, sobald er erledigt ist.',
    'everything_your_people_see_of_your_brand_on_one_page_th_9d98e332' => 'Ihre gesamte Markendarstellung auf einer Seite: Logo, Favicon, Farben, Schrift und Ecken der gehosteten Anmeldung mit Live-Vorschau sowie Produktname, E-Mail-Absender und Willkommensmail. Legen Sie die Gestaltung einmal für die gesamte Umgebung fest; alle Organisationen übernehmen sie. Alternativ können Sie einer Organisation im Tab „Branding“ ein eigenes Erscheinungsbild geben.',
    'from_the_next_attempt_blocks_refuse_sign_ins_and_sign_u_e89996c3' => 'Ab dem nächsten Versuch verhindern Sperren Anmeldungen und Registrierungen in dieser Umgebung. Prüfaufforderungen verlangen eine zusätzliche Verifizierung. Ist eine Regel falsch, werden echte Personen ausgesperrt.',
    'grant_one_to_the_people_who_support_or_run_your_apps_an_3991d001' => 'Gewähren Sie eines den Personen, die Ihre Apps unterstützen oder ausführen. Die eigene Rolle einer App erreicht nur die Token dieser App; Eine Rolle für alle Apps erreicht jede einzelne von ihnen.',
    'how_many_organizations_users_single_sign_on_connections_8e80258f' => 'Die Anzahl der Organisationen, Benutzer, Single-Sign-on-Verbindungen, Apps und Benutzersynchronisierungen in dieser Umgebung, jeweils mit einem Link zur zugehörigen Seite. Über die Verknüpfungen darunter können Sie häufig benötigte Einträge erstellen: eine Organisation, einen Benutzer, eine Single-Sign-on-Verbindung oder eine App.',
    'how_many_people_signed_in_and_how_often_your_apps_calle_bc3b092f' => 'Wie viele Personen sich in den letzten 30 Tagen angemeldet haben und wie oft Ihre Apps die API aufgerufen haben. Diese Übersicht hilft, die Auslastung einzuschätzen und Auffälligkeiten zu erkennen. Sie ist keine Rechnung.',
    'how_often_to_pull_and_which_of_the_hr_system_s_own_fiel_54dd88fe' => 'Wie oft Daten abgerufen werden und welche Felder des HR-Systems für jede Person übernommen werden, etwa Kostenstelle oder Standort. Wenn Sie die Felder ändern, erfolgt beim nächsten Durchlauf eine vollständige Synchronisierung.',
    'how_the_audit_trail_leaves_cbox_id_a_scheduled_export_s_3da9deb4' => 'So werden Audit-Daten aus Cbox ID exportiert: Alle fünf Minuten überträgt ein geplanter Export neue Einträge an Ihr SIEM oder Archiv. Ein täglicher Aufbewahrungsauftrag erstellt einen Prüfpunkt des Audit-Protokolls, ohne Daten zu löschen. Hier können Sie den Auditverlauf einer Person für ein DSGVO-Auskunftsersuchen abrufen oder in einer Umgebungskonsole prüfen, ob die Exporte laufen.',
    'if_the_app_declares_a_different_url_later_this_approval_d8bd0ea4' => 'Wenn die App später eine andere URL angibt, wird diese Genehmigung aufgehoben und erneut angefordert. Eine Änderung des Ziels, an das Passwörter gesendet werden, darf nicht unbemerkt übernommen werden. Die delegierte Anmeldung dient dem schrittweisen Umstieg. Sobald nur noch wenige Personen das alte System nutzen, deaktivieren Sie sie und senden Sie diesen Personen einen Link zum Zurücksetzen des Passworts.',
    'it_stops_appearing_as_a_button_and_its_credentials_are_120d1fa5' => 'Die Schaltfläche wird entfernt und die Zugangsdaten werden gelöscht. Alle, die sich darüber angemeldet haben, behalten ihr Konto und können weiterhin ihr Passwort verwenden. Wenn Sie die Zugangsdaten behalten möchten, deaktivieren Sie die Verbindung stattdessen.',
    'its_scopes_go_with_it_apps_that_held_them_keep_them_as_bf31a699' => 'Die zugehörigen Berechtigungsbereiche werden ebenfalls entfernt. Apps behalten diese als frei eingegebene Berechtigungsbereiche, die keinen Zugriff mehr auf diese API gewähren. Bereits ausgestellte Tokens funktionieren bis zu ihrem Ablauf weiter.',
    'keys_for_an_environment_s_management_api_run_one_enviro_6197b6d2' => 'Schlüssel für die Verwaltungs-API einer Umgebung: Verwalten Sie die Organisationen, Mitglieder, Einladungen, Rollen und Apps einer Umgebung aus Ihrem eigenen Backend. Jeder Schlüssel hat ausdrücklich festgelegte Berechtigungsbereiche.',
    'keys_this_organization_s_people_have_created_for_its_ap_9d7e0611' => 'Schlüssel, die Personen dieser Organisation für deren Apps erstellt haben, mit den jeweiligen Berechtigungen. Jede Person erstellt ihre eigenen Schlüssel. Widerrufen Sie Schlüssel, die offengelegt wurden oder nicht mehr verwendet werden.',
    'leave_it_empty_for_almost_every_provider_its_id_tokens_e39d64b9' => 'Lassen Sie dieses Feld bei fast allen Anbietern leer: Deren ID-Tokens werden anhand der im Discovery-Dokument veröffentlichten Signaturschlüssel (jwks_uri) geprüft, auch nach Schlüsselrotationen. Fügen Sie den öffentlichen PEM-Schlüssel des Anbieters nur ein, wenn er keine Schlüssel veröffentlicht.',
    'let_people_sign_in_with_an_account_they_already_have_se_de3c77a6' => 'Ermöglichen Sie die Anmeldung mit einem bereits vorhandenen Konto. Richten Sie einen Anbieter einmal für die Umgebung ein, damit alle Organisationen ihn anbieten. Eine Organisation kann stattdessen eigene Zugangsdaten verwenden oder einen Anbieter deaktivieren.',
    'let_the_people_who_use_your_apps_connect_their_own_gith_19a2d0ed' => 'Ermöglichen Sie den Benutzern Ihrer Apps, ihr eigenes GitHub-, Google-, Slack- oder Salesforce-Konto zu verbinden, damit Ihre Apps die jeweiligen APIs in ihrem Namen aufrufen können. Die Tokens werden verschlüsselt gespeichert, hier erneuert und nur den von Ihnen autorisierten Apps zeitlich begrenzt bereitgestellt.',
    'lets_your_people_sign_in_with_the_company_account_they_5186cda3' => 'Ermöglicht Ihrem Team die Anmeldung mit dem vorhandenen Unternehmenskonto bei Microsoft Entra ID, Okta oder Google Workspace anstelle eines separaten Passworts hier. Sie verbinden Ihren Identitätsanbieter einmal und bestätigen Ihre E-Mail-Domains. Personen mit diesen Domains werden anschließend zur Anmeldung an Ihren Anbieter weitergeleitet.',
    'letting_your_people_sign_in_with_entra_id_okta_or_googl_10c80076' => 'Die Anmeldung mit Entra ID, Okta oder Google Workspace ist im Enterprise-Tarif verfügbar. Wenden Sie sich an Ihr Betreuungsteam, um sie für diese Organisation zu aktivieren.',
    'links_handed_to_this_organization_s_it_administrator_th_65719b81' => 'Noch gültige Links, die dem IT-Administrator dieser Organisation übergeben wurden. Ein widerrufener Link funktioniert sofort nicht mehr. Bereits darüber vorgenommene Einrichtungen bleiben erhalten.',
    'looks_up_an_organization_by_name_or_handle_or_a_user_by_d7460886' => 'Sucht Organisationen anhand ihres Namens oder Kurznamens und Benutzer anhand ihres Namens oder ihrer E-Mail-Adresse in allen Umgebungen dieser Installation, nicht nur in der aktuell geöffneten. Verwenden Sie diese Suche bei Supportanfragen, wenn Sie nicht wissen, in welcher Umgebung sich die Person befindet.',
    'metadata_schemas_are_a_subset_of_json_schema_an_object_64eba270' => 'Metadatenschemas verwenden eine Teilmenge von JSON Schema: ein Objekt mit Eigenschaften vom Typ Zeichenfolge, Zahl, Ganzzahl, boolescher Wert oder null sowie Vorgaben für Aufzählungswerte, Länge, Wertebereich, Muster und Format. Jede gespeicherte Änderung erzeugt eine neue Version. Bereits erfasste Ereignisse behalten die Version, anhand derer sie geprüft wurden.',
    'mirrors_every_audit_log_entry_into_your_security_team_s_b980f702' => 'Überträgt jeden neuen Audit-Protokolleintrag sofort in die Werkzeuge Ihres Sicherheitsteams, etwa ein SIEM. So können Untersuchungen in den bereits verwendeten Werkzeugen beginnen, ohne zunächst einen Export anzufordern. Die Zustellung erfolgt mindestens einmal; gelegentliche Duplikate sind daher möglich.',
    'most_integrations_want_webhooks_instead_those_run_after_576be07b' => 'Für die meisten Integrationen eignen sich Webhooks besser: Sie werden nach dem Ereignis ausgeführt und können den Vorgang nicht blockieren. Verwenden Sie einen Hook nur, wenn Ihr eigenes System während einer Anmeldung oder Token-Ausstellung Einfluss nehmen muss.',
    'no_new_secret_is_issued_from_the_next_attempt_retries_i_eba13c7b' => 'Es wird kein neues Geheimnis ausgestellt. Ab dem nächsten Zustellversuch, einschließlich Wiederholungen, werden die Header des anderen Verfahrens verwendet. Ein nicht aktualisierter Empfänger lehnt dann jede Zustellung ab.',
    'nobody_is_on_this_workspace_it_has_no_owner_so_nobody_c_554101fb' => 'Dieser Arbeitsbereich hat keine Mitglieder und keinen Eigentümer. Daher kann sich niemand zu seiner Verwaltung anmelden. Dies deutet auf einen Fehler bei der Bereitstellung hin, der untersucht werden sollte, und nicht lediglich auf eine leere Liste.',
    'nothing_is_always_refused_and_nothing_skips_the_rules_d_6699d9d9' => 'Keine Einträge werden immer abgelehnt oder von den Regeln ausgenommen. Sperren Sie einen Adressbereich, von dem Angriffe ausgehen, oder nehmen Sie Ihr Büronetz von den Regeln zur Anmeldehäufigkeit aus.',
    'offers_google_github_apple_and_others_as_buttons_on_you_82b5af03' => 'Bietet Google, GitHub, Apple und weitere Anbieter als Schaltflächen auf Ihrer Anmeldeseite an, damit Personen ein vorhandenes Konto statt eines weiteren Passworts nutzen können. Richten Sie einen Anbieter einmal für die Umgebung ein; alle Organisationen bieten ihn dann an. Eine Organisation kann eigene Zugangsdaten verwenden oder einen Anbieter deaktivieren. Sie stellen die Zugangsdaten bereit, alles Weitere wird automatisch ausgefüllt. Eine vom Anbieter übermittelte E-Mail-Adresse allein reicht niemals aus, um auf ein bestehendes Konto hier zuzugreifen.',
    'on_for_this_percentage_of_everyone_the_rules_above_do_n_6ca1e886' => 'Aktiviert für diesen Prozentsatz der Personen, auf die keine der obigen Regeln zutrifft. Ein stabiler Hash der Benutzer-ID sorgt dafür, dass immer dieselben Personen ausgewählt werden; eine Erhöhung fügt nur weitere hinzu. Lassen Sie das Feld leer, wenn keine schrittweise Freigabe gewünscht ist.',
    'one_marked_event_siem_stream_test_sent_now_with_this_st_c0cf0c4a' => 'Ein gekennzeichnetes Ereignis (siem.stream.test) wird jetzt mit den Einstellungen und Zugangsdaten dieses Streams gesendet, ohne Warteschlange und ohne Wiederholung. Bei Erfolg wird auch der Hinweis „Handlung erforderlich“ aufgehoben.',
    'one_per_line_including_the_scheme_https_app_example_com_71de2531' => 'Ein Eintrag pro Zeile einschließlich Protokoll, etwa https://app.example.com. Ist eine Zeile ungültig, wird die gesamte Liste abgelehnt. Fehlerhafte Zeilen werden nicht stillschweigend verworfen.',
    'one_type_per_resource_type_its_relation_s_below_it_a_re_18943de8' => 'Ein `type` pro Ressourcentyp, darunter die zugehörigen `relation`s. Eine Relation wird durch direkt im Tupel benannte Subjekte ([user, group#member]), eine andere Relation (owner), eine Relation des übergeordneten Objekts (viewer from parent) oder eine Verknüpfung mit or, and oder but not bestimmt.',
    'one_workspace_on_this_install_its_team_its_projects_and_e343ed1c' => 'Ein Arbeitsbereich in dieser Installation mit seinem Team, seinen Projekten und allen zugehörigen Umgebungen. Eine Sperrung meldet seine Mitglieder ab und stoppt die Authentifizierung in allen diesen Umgebungen.',
    'only_for_a_provider_that_does_not_publish_its_signing_k_e4c5eb2d' => 'Nur für Anbieter, die keine Signaturschlüssel (jwks_uri) in ihrem Discovery-Dokument veröffentlichen. Andernfalls werden die Schlüssel dort abgerufen, auch nach Rotationen. Geben Sie einen öffentlichen PEM-Schlüssel an. Er wird verschlüsselt gespeichert und nicht erneut angezeigt. Lassen Sie das Feld leer, um den aktuellen Schlüssel zu behalten.',
    'only_the_active_members_of_the_organization_you_choose_a4a82dec' => 'Nur aktive Mitglieder der ausgewählten Organisation können sich bei dieser Anwendung anmelden. Alle anderen werden abgewiesen; die Ablehnung wird im Audit-Protokoll erfasst.',
    'organization_detail_in_the_target_environment_members_s_caef589f' => 'Details zur Organisation in der Zielumgebung: Mitglieder, SSO, Domains, Leistungsberechtigungen und letzte Aktivitäten. Auf dieser Seite lässt sich ausschließlich der Status der Organisation ändern.',
    'organizations_users_and_active_sessions_for_every_envir_b7f36bfd' => 'Organisationen, Benutzer und aktive Sitzungen aller Umgebungen dieser Installation sowie die Organisationen mit den meisten Mitgliedern. Diese Ansicht liest nur Daten und ändert niemals die in der Konsole ausgewählte Umgebung.',
    'pick_the_framework_you_are_building_with_and_an_app_is_a82b6a71' => 'Wählen Sie Ihr Framework. Dafür wird eine App mit Weiterleitung zu Ihrem lokalen Entwicklungsserver, einem Umgebungsvariablenblock zum Kopieren und dem Code zur Anmeldung einer Person erstellt. Die Seite wartet, bis sich tatsächlich jemand anmeldet. Darunter finden Sie die weiteren Schritte zum fertigen Produkt: Branding, Organisationen, Single Sign-on, ein Agent, ein Teammitglied und Produktivbetrieb. Jeder Schritt wird anhand des tatsächlichen Zustands dieser Umgebung automatisch abgehakt, niemals manuell.',
    'platform_operators_administer_every_workspace_and_envir_fb24c050' => 'Plattformbetreiber verwalten alle Arbeitsbereiche und Umgebungen dieser Installation auf einer übergeordneten Ebene. Ernennen Sie nur Personen zu Plattformbetreibern, die die Installation selbst betreiben. Sperren Sie ihren Zugriff, sobald sie diese Aufgabe nicht mehr übernehmen.',
    'point_an_identity_provider_at_our_scim_endpoint_connect_9f06ef10' => 'Verbinden Sie einen Identitätsanbieter mit unserem SCIM-Endpunkt, binden Sie Google Workspace oder Microsoft Entra an oder verbinden Sie Ihr HR-System: Workday, BambooHR, Rippling, HiBob oder Personio. Aus den verbundenen Systemen rufen wir Ihre Personaldaten regelmäßig ab.',
    'prove_which_email_domains_your_organization_owns_a_veri_a1717fad' => 'Bestätigen Sie, welche E-Mail-Domains Ihrer Organisation gehören. Eine verifizierte Domain kann alle Personen mit einer zugehörigen Adresse direkt zu Ihrer Unternehmens-SSO-Verbindung weiterleiten.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_96651d15' => 'Radar bewertet jede Anmeldung und Registrierung auf die Wiederverwendung gestohlener Zugangsdaten, botähnliche Geschwindigkeit, unmögliche Ortswechsel, neue Geräte, anonymisierende Netzwerke und Wegwerfadressen. Hinzu kommen Ihre eigenen Regeln sowie Zulassungs- und Sperrlisten. Jede Entscheidung wird protokolliert. Sobald Sie die Durchsetzung aktivieren, blockiert Radar Zugriffe oder fordert einen zweiten Faktor an. Prüfen Sie die Entscheidungen hier vor der Aktivierung und wenn jemand Probleme bei der Anmeldung meldet.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_9c16eda1' => 'Radar bewertet jede Anmeldung und Registrierung auf die Wiederverwendung gestohlener Zugangsdaten, botähnliche Geschwindigkeit, unmögliche Ortswechsel, neue Geräte, anonymisierende Netzwerke und Wegwerfadressen sowie anhand Ihrer eigenen Regeln und Listen. Die Gründe für die Entscheidung werden protokolliert.',
    'refuse_passwords_found_in_known_data_breaches_checked_a_db4c6959' => 'Passwörter aus bekannten Datenlecks ablehnen. Die Prüfung erfolgt über Have I Been Pwned, ohne jemals das Passwort zu senden. Ist der Dienst nicht erreichbar, bleibt die Registrierung erlaubt und wird nicht blockiert.',
    'registers_applications_that_accept_this_environment_as_d381d96e' => 'Registriert Anwendungen, die diese Umgebung als SAML-Identitätsanbieter akzeptieren. Deren Benutzer melden sich mit ihren bereits vorhandenen Konten hier an. Ordnen Sie jeder Anwendung ihre Organisation zu, damit nur deren Mitglieder zugelassen werden. Ohne Zuordnung steht sie allen Personen in der Umgebung offen. Dies ist die ausgehende Richtung. Für die Anmeldung mit einem externen Unternehmenskonto verwenden Sie Unternehmens-SSO unter Authentifizierung.',
    'requests_appear_here_on_their_own_when_an_app_or_agent_2ee57630' => 'Anfragen erscheinen hier automatisch, wenn eine App oder ein Agent Ihre Genehmigung benötigt, um in Ihrem Namen zu handeln. Bis dahin müssen Sie nichts tun. Lehnen Sie Anfragen ab, die Sie nicht selbst ausgelöst haben.',
    'requests_from_agents_asking_to_act_on_a_user_s_behalf_a_c8d607b8' => 'Anfragen von Agenten, die im Namen eines Benutzers handeln möchten, erscheinen hier bei Eingang. Jeder Benutzer genehmigt seine eigenen Anfragen. Auf dieser Seite können Sie Anfragen ablehnen, die auf Missbrauch hindeuten.',
    'right_now_people_sign_in_with_credentials_held_here_con_4538c692' => 'Derzeit melden sich Personen mit hier gespeicherten Zugangsdaten an. Verbinden Sie Ihren Anbieter, damit sie ihr vorhandenes Unternehmenskonto verwenden können. Sobald Sie dieses Konto beim Anbieter deaktivieren, verlieren sie auch hier den Zugriff.',
    'scopes_sign_out_uris_token_settings_and_the_roles_manif_c736e69a' => 'Berechtigungsbereiche, Abmelde-URIs, Token-Einstellungen und die URL des Rollenmanifests werden unverändert kopiert. Geheimnisse, Schlüssel und die Benutzer der App werden nicht kopiert. Sie gehören zu der Umgebung, in der sie angelegt wurden.',
    'see_an_app_exactly_as_one_of_its_users_does_you_sign_in_8eafae42' => 'Sehen Sie eine App genau wie einer ihrer Benutzer: Sie melden sich für einen angegebenen Grund und höchstens eine Stunde als diese Person an. Die App erfährt Ihre tatsächliche Identität und erhält keine Möglichkeit, die Sitzung dauerhaft fortzusetzen. Im Audit-Protokoll der Organisation wird erfasst, wer dies getan hat und warum.',
    'send_this_single_use_link_to_whoever_configures_your_id_e8056999' => 'Senden Sie diesen einmaligen Link an die Person, die Ihren Identitätsanbieter konfiguriert. Er läuft bald ab und funktioniert ohne Konto. Kopieren Sie ihn jetzt; er wird nur einmal angezeigt.',
    'send_this_single_use_link_to_whoever_runs_their_identit_ecdd3fd5' => 'Senden Sie diesen einmaligen Link an die Person, die den Identitätsanbieter der Organisation verwaltet, falls er ihr nicht bereits per E-Mail zugestellt wurde. Er funktioniert bis zum Ablauf ohne Konto. Kopieren Sie ihn jetzt; er wird nur einmal angezeigt.',
    'serves_an_environment_s_identity_endpoints_on_a_domain_f6582d38' => 'Stellt die Identitätsendpunkte einer Umgebung unter Ihrer eigenen Domain bereit, etwa login.example.com, statt unter unserer. Sie bestätigen die Inhaberschaft mit einem DNS-TXT-Eintrag. Richten Sie dies ein, wenn Personen bei der Anmeldung ausschließlich Ihre eigene Adresse sehen sollen.',
    'set_this_as_the_role_s_trust_policy_iam_roles_trust_rel_d432cbe5' => 'Legen Sie dies als Vertrauensrichtlinie der Rolle fest (IAM › Roles › Trust relationships). Die Plattform darf die Rolle nur übernehmen, wenn sie die externe ID dieses Streams vorlegt. So kann niemand sonst auf dieser Plattform einen Stream auf Ihre Rolle ausrichten.',
    'sign_ins_and_requests_that_cbox_id_scored_as_risky_enou_b09e917e' => 'Anmeldungen und Anfragen, die Cbox ID als auffällig eingestuft hat, mit den neuesten zuerst sowie Risikowert und Begründung. Prüfen Sie diese Übersicht bei einem Anstieg fehlgeschlagener Anmeldungen oder wenn jemand eine fremde Anmeldung meldet.',
    'sign_ins_tokens_issued_new_users_and_two_factor_enrolme_e9040ee7' => 'Anmeldungen, ausgestellte Tokens, neue Benutzer und aktivierte Zwei-Faktor-Authentifizierungen pro Tag für die letzten 30 Tage, sofern für die Installation kein anderer Zeitraum festgelegt wurde. Die Seite bleibt leer, bis der Betreiber einen Speicherort für Analysedaten konfiguriert hat.',
    'snapshots_every_admin_support_role_each_role_held_acros_351f6f6d' => 'Erfasst alle Verwaltungs- und Supportrollen in der gesamten Umgebung als Einträge zur Bestätigung oder zum Widerruf. Ein Widerruf entzieht die Rolle gleichzeitig in allen Organisationen.',
    'software_that_acts_on_this_environment_with_a_managemen_24a4b34d' => 'Software, die mit einem Verwaltungsschlüssel in dieser Umgebung arbeitet, etwa Claude Code, Cursor, ein interner Bot oder Ihr eigenes Backend. Jede Anwendung erhält nur die von Ihnen zugewiesenen Berechtigungsbereiche und wartet bei den festgelegten Aktionen auf Ihre Genehmigung.',
    'some_pairs_of_roles_must_never_sit_with_the_same_person_70e4454a' => 'Bestimmte Rollen dürfen niemals derselben Person zugewiesen werden. Wer eine Zahlung anlegt, sollte sie nicht selbst freigeben. Definieren Sie diese Rollenpaare hier. Cbox ID verhindert neue Zuweisungen, die gegen die Regel verstoßen, und zeigt Personen an, die bereits beide Rollen besitzen.',
    'splunk_elastic_graylog_cef_and_generic_json_are_http_co_8d405816' => 'Splunk, Elastic, Graylog, CEF und Generic JSON sind HTTP-Empfänger, für die Sie eine URL angeben. Datadog, Amazon S3 und Google Cloud Storage verwenden jeweils eigene Einstellungen.',
    'start_from_the_documents_in_folders_example_owners_edit_ca2a0af5' => 'Beginnen Sie mit dem Beispiel für Dokumente in Ordnern: Eigentümer, Bearbeiter und Betrachter, wobei die Zugriffsrechte eines Ordners an alle darin enthaltenen Objekte vererbt werden. Für Tupel und Berechtigungsprüfungen muss zuerst ein Schema vorhanden sein.',
    'switches_your_apps_ask_about_for_one_person_in_one_orga_e232d9a9' => 'Funktionsschalter, die Ihre Apps für eine Person in einer Organisation abfragen. Aktivieren Sie eine Funktion für bestimmte Benutzer, bestimmte Organisationen oder einen Anteil aller Personen. Jede App erhält dieselbe Antwort, im Token oder über die API.',
    'the_address_tokens_for_this_api_name_as_their_audience_cdea85aa' => 'Die Adresse, die Tokens für diese API als Zielgruppe nennen und die Ihre API prüft. Sie lässt sich später nicht ändern, da bereits ausgestellte Tokens diesen Wert enthalten.',
    'the_agent_is_refused_and_cannot_act_on_this_person_s_be_e1cd49d2' => 'Die Anfrage des Agenten wird abgelehnt. Er kann nicht im Namen dieser Person handeln. Die Ablehnung wird im Audit-Protokoll erfasst und lässt sich nicht rückgängig machen. Der Agent muss eine neue Anfrage stellen.',
    'the_audit_events_your_app_sends_about_each_organization_a385fa1d' => 'Die Audit-Ereignisse, die Ihre App für jede betreute Organisation sendet: wer wann was in Ihrem Produkt getan hat. Sie werden je Organisation in einer Hash-Kette gespeichert und den jeweiligen Organisationsadministratoren angezeigt. Verwenden Sie dies, wenn eine Organisation ein Audit-Protokoll für ihr Konto anfordert. Definieren Sie Schemas, damit die Ereignisse einheitlich bleiben.',
    'the_audit_events_your_app_sends_about_the_organizations_19cde284' => 'Die von Ihrer App gesendeten Audit-Ereignisse für alle betreuten Organisationen, mit den neuesten zuerst. Die Ereignisse jeder Organisation bilden eine eigene Hash-Kette.',
    'the_audit_trail_lives_here_and_your_security_team_s_too_621820fa' => 'Das Audit-Protokoll liegt hier, die Werkzeuge Ihres Sicherheitsteams an anderer Stelle. Ein Stream überträgt jeden neuen Eintrag sofort dorthin. So beginnt eine Untersuchung nicht erst mit der Bitte um einen CSV-Export.',
    'the_button_disappears_from_this_organization_s_sign_in_88a1cc4f' => 'Die Schaltfläche verschwindet von der Anmeldeseite dieser Organisation. Der eigene Anbieter der Umgebung tritt nicht an ihre Stelle. Die Zugangsdaten bleiben erhalten, sodass Sie die Verbindung wieder aktivieren können.',
    'the_ceiling_on_this_app_s_access_narrowing_it_takes_eff_5f2865bc' => 'Die Obergrenze für den Zugriff dieser App. Eine Einschränkung gilt ab dem nächsten Token. Fordert ein Gerät oder Agent einen entfernten Berechtigungsbereich an, wird die Anfrage abgelehnt, statt stillschweigend weniger Rechte zu erteilen.',
    'the_destination_refused_the_settings_a_missing_bucket_a_27207d67' => 'Das Ziel hat die Einstellungen abgelehnt, etwa wegen eines fehlenden Buckets oder einer falschen Region bzw. eines falschen Standorts. Bis zur Korrektur wird nichts zugestellt. Einträge bleiben in der Warteschlange und werden nicht verworfen.',
    'the_email_domains_this_organization_owns_each_proved_wi_02a41e13' => 'Die E-Mail-Domains dieser Organisation, jeweils durch einen DNS-TXT-Eintrag bestätigt. Nach der Verifizierung können Sie die verpflichtende Weiterleitung aktivieren. Alle Personen mit einer Adresse dieser Domain werden dann zur Unternehmens-SSO-Verbindung statt zur Passwortanmeldung geleitet. Verifizieren Sie daher alle von Ihrem Team verwendeten Domains, bevor Sie sich auf Single Sign-on verlassen.',
    'the_keys_your_own_code_presents_to_cbox_id_one_tab_per_42243556' => 'Die Schlüssel, mit denen Ihr eigener Code auf Cbox ID zugreift, mit einem Tab pro Schlüsselart. Ein geheimer Verwaltungsschlüssel lässt Ihr Backend die Organisationen, Mitglieder, Einladungen, Rollen und Apps einer Umgebung verwalten. Ein Arbeitsbereichsschlüssel ruft die Arbeitsbereichs-API mit einer integrierten Rolle auf. Ein veröffentlichbarer Schlüssel wird in einer Browser-App verwendet und funktioniert nur von den erlaubten Origins aus. Geheime Schlüssel und Arbeitsbereichsschlüssel werden nur einmal angezeigt. Kopieren Sie sie beim Erstellen und widerrufen Sie sie sofort, falls sie offengelegt werden.',
    'the_mirror_image_cbox_id_pushes_your_people_into_the_ot_19c0ed40' => 'Die Gegenrichtung: Cbox ID überträgt Ihre Benutzer über die SCIM-Endpunkte in andere SaaS-Produkte Ihres Unternehmens. So verwalten Sie Ein- und Austritte zentral statt in einem eigenen Administrationsbereich je Anbieter.',
    'the_name_of_your_workspace_which_your_projects_environm_3fa3245f' => 'Der Name Ihres Arbeitsbereichs, dem Projekte, Umgebungen und Team zugeordnet sind und den die Konsole überall anzeigt. Das Löschen eines Arbeitsbereichs legt alle zugehörigen Anmeldeumgebungen still. Deshalb ist dafür eine Supportanfrage erforderlich; es gibt keine Schaltfläche zum Löschen.',
    'the_password_rules_lockout_two_factor_requirement_and_s_6d5c4102' => 'Passwortregeln, Kontosperre, Zwei-Faktor- und Single-Sign-on-Pflicht bei jeder Anmeldung sowie umgebungsweit die Verfügbarkeit von Passkeys und Anmeldelinks und die Sitzungsdauer. Die Umgebung legt die Basis fest, die jede Organisation übernimmt. Organisationen können Passwort- und Zwei-Faktor-Regeln verschärfen, aber niemals abschwächen.',
    'the_services_of_yours_that_receive_access_tokens_and_th_8f7e35e1' => 'Ihre Dienste, die Zugriffstokens empfangen, und die Berechtigungsbereiche jedes Dienstes. Sie entscheiden, wer die Berechtigungsbereiche einer registrierten API erhält. Niemand kann sie einfach bei einer App eintragen, um Zugriff auf Ihre API zu bekommen.',
    'the_whole_environment_offers_it_on_every_sign_in_page_c_6d75dee5' => 'Die gesamte Umgebung bietet diesen Anbieter auf jeder Anmeldeseite an. Wählen Sie eine Organisation aus, um stattdessen einen eigenen Anbieter einzurichten. Dieser ersetzt dann den Anbieter der Umgebung auf der Anmeldeseite dieser Organisation.',
    'the_workspace_s_own_keys_for_the_workspace_api_list_pro_d42a9e3f' => 'Die eigenen Schlüssel des Arbeitsbereichs für die Arbeitsbereichs-API: Projekte und Umgebungen auflisten, Umgebungen erstellen sowie Teammitglieder auflisten und einladen. Jeder Schlüssel hat eine integrierte Rolle.',
    'their_sessions_and_tokens_are_revoked_their_passkeys_se_78603573' => 'Die Sitzungen und Tokens werden widerrufen. Passkeys, zweite Faktoren, Mitgliedschaften, Rollenzuweisungen, API-Tokens, Tresorgeheimnisse, Geräte und alle gespeicherten Kopien der persönlichen Daten werden gelöscht. Das Konto bleibt nur als pseudonymisierter, deaktivierter Datensatz erhalten. Apps, die Personen von hier synchronisieren, erhalten eine Löschanweisung. Das Audit-Protokoll behält die nicht sprechende ID, nicht den Namen oder die E-Mail-Adresse.',
    'these_run_in_the_middle_of_an_operation_not_after_it_an_c325ec80' => 'Diese Hooks werden während eines Vorgangs ausgeführt, nicht danach. Ihre Antwort beeinflusst das Ergebnis: Ihr Endpunkt kann einem Token Informationen hinzufügen oder eine Anmeldung vollständig ablehnen. Damit greifen sie direkt in den Ablauf ein. Ein langsamer oder fehlerhafter Endpunkt wirkt sich unmittelbar auf die Person aus, die sich anmelden möchte.',
    'they_lose_access_to_every_platform_page_on_this_install_0e71b790' => 'Die Person verliert sofort den Zugriff auf alle Plattformseiten dieser Installation. Bestehende Sitzungen funktionieren ab der nächsten Anfrage nicht mehr. Sie können die Person hier wieder aktivieren.',
    'this_cannot_be_undone_their_credentials_memberships_and_0d29eed0' => 'Dies kann nicht rückgängig gemacht werden. Zugangsdaten, Mitgliedschaften und persönliche Daten werden gelöscht; das Konto wird pseudonymisiert. Ist die Person alleiniger Eigentümer einer Organisation, übertragen Sie zuerst das Eigentum.',
    'this_deployment_has_no_turnstile_keys_cbox_id_turnstile_9ceda61f' => 'Für diese Installation sind keine Turnstile-Schlüssel hinterlegt (CBOX_ID_TURNSTILE_SITE_KEY). Daher lässt sich keine Turnstile-Prüfung aktivieren. Bei einer auffälligen Registrierung wird stattdessen die E-Mail-Adresse bestätigt.',
    'this_endpoint_belongs_to_the_environment_and_fires_for_2bbbb6fd' => 'Dieser Endpunkt gehört zur Umgebung und wird für jede darin enthaltene Organisation ausgelöst. Er wird hier angezeigt, weil er bei Ihren Anmeldungen ausgeführt wird. Verwaltet wird er vom Betreiber.',
    'this_environment_serves_an_mcp_server_next_to_its_rest_8094252a' => 'Diese Umgebung stellt neben ihrer REST-API einen MCP-Server bereit. Verbinden Sie einen Agenten mit einem Verwaltungsschlüssel damit. Er kann genau die durch dessen Berechtigungsbereiche erlaubten Aktionen ausführen, mit denselben Prüfungen, Genehmigungen und Audit-Protokollen wie in der Konsole.',
    'this_environment_serves_an_mcp_server_the_standard_way_eb9faa22' => 'Diese Umgebung stellt neben ihrer REST-API einen MCP-Server bereit, die Standardschnittstelle für Werkzeugaufrufe durch KI-Assistenten. Tragen Sie die Adresse und einen Verwaltungsschlüssel in Claude Code, Cursor oder einen anderen MCP-Client ein. Der Agent kann genau die erlaubten Aktionen ausführen, mit denselben Prüfungen und demselben Audit-Protokoll wie in der Konsole.',
    'this_user_can_no_longer_sign_in_to_any_application_in_t_571ac0d8' => 'Dieser Benutzer kann sich bei keiner Anwendung dieser Umgebung mehr anmelden. Bestehende Sitzungen funktionieren ab der nächsten Anfrage nicht mehr. Seine Datensätze bleiben erhalten und Sie können ihn jederzeit wieder aktivieren.',
    'this_user_owns_or_administers_an_organization_and_those_941764ef' => 'Dieser Benutzer ist Eigentümer oder Administrator einer Organisation. Für solche Konten ist keine Identitätsübernahme zulässig, da dadurch dauerhafte Kontrolle über eine Organisation erlangt werden könnte.',
    'today_somebody_adds_and_removes_people_here_by_hand_con_01774e72' => 'Derzeit werden Personen hier manuell hinzugefügt und entfernt. Verbinden Sie das bestehende Unternehmensverzeichnis, damit beides automatisch geschieht, einschließlich der leicht vergessenen Entfernung ehemaliger Benutzer.',
    'until_an_api_is_registered_a_scope_is_just_text_on_an_a_db7d3254' => 'Solange keine API registriert ist, ist ein Berechtigungsbereich nur Text in einer App. Wer die App bearbeiten darf, kann ihr beliebige Berechtigungsbereiche zuweisen. Registrieren Sie die von Ihren Apps aufgerufenen APIs, damit deren Berechtigungsbereiche einen Eigentümer haben.',
    'verified_domains_route_people_to_your_own_identity_prov_127a9e78' => 'Verifizierte Domains leiten Personen an Ihren eigenen Identitätsanbieter weiter. Diese Funktion ist Teil des Enterprise-Tarifs. Wenden Sie sich an Ihr Betreuungsteam, um sie für diese Organisation zu aktivieren.',
    'verifying_a_domain_you_own_acme_com_lets_cbox_id_recogn_7a9ae408' => 'Wenn Sie eine eigene Domain wie acme.com verifizieren, erkennt Cbox ID Ihre Benutzer anhand ihrer E-Mail-Adresse und leitet sie direkt an Ihren Anbieter weiter. So muss niemand die richtige Anmeldeschaltfläche auswählen.',
    'webhooks_sign_out_notices_to_connected_apps_role_update_776577f9' => 'Webhooks, Abmeldemitteilungen an verbundene Apps, der Abruf von Rollenaktualisierungen und E-Mails in der Warteschlange werden von Hintergrundprozessen verarbeitet, ohne Personen warten zu lassen. Ohne laufenden Queue-Worker wird nichts davon verarbeitet, während die übrige Konsole unauffällig bleibt. Auf dieser Seite erkennen Sie das Problem.',
    'what_agents_in_this_environment_are_waiting_for_a_perso_8f2ea5c0' => 'Die Aktionen von Agenten in dieser Umgebung, die auf eine Genehmigung warten. Benötigt der Schlüssel eines Agenten eine Genehmigung, hält er an und fragt die Person, die den Schlüssel erstellt hat. Diese kann am Telefon oder hier antworten. Wer die Umgebung verwaltet, kann verdächtige Anfragen ablehnen. Darunter stehen Anfragen von Apps, die im Namen eines Benutzers handeln möchten. Diese genehmigt jeder Benutzer selbst.',
    'what_an_app_may_be_allowed_to_do_at_this_api_your_own_a_94f7133a' => 'Die Berechtigungen, die eine App bei dieser API erhalten darf. Ihre eigenen Apps können alle erhalten. Von einer Organisation registrierte Apps dürfen nur die für Organisationen freigegebenen Berechtigungen erhalten.',
    'what_software_in_this_environment_is_waiting_for_a_pers_7aa0659a' => 'Die Aktionen von Software in dieser Umgebung, die auf eine Genehmigung warten. Ein Agent, dessen Schlüssel eine Genehmigung benötigt, hält an und fragt die Person, die den Schlüssel erstellt hat. Antworten Sie hier oder auf Ihrem Telefon.',
    'what_your_code_asks_for_and_what_the_feature_flags_clai_440d8ca1' => 'Der Schlüssel, den Ihr Code abfragt und den der Claim feature_flags enthält. Kleinbuchstaben und Ziffern, dazwischen - _ oder . zulässig. Der Schlüssel lässt sich später nicht ändern.',
    'when_an_app_or_an_ai_agent_needs_your_go_ahead_to_act_a_51a99858' => 'Wenn eine App oder ein KI-Agent Ihre Genehmigung benötigt, um in Ihrem Namen zu handeln, kann die Anfrage nicht immer direkt auf dem verwendeten Bildschirm erscheinen. Deshalb wird sie hier angezeigt. Genehmigen Sie nur selbst ausgelöste Anfragen und prüfen Sie, ob der angezeigte Code mit dem auf dem anfragenden Gerät übereinstimmt.',
    'when_every_condition_holds_radar_takes_this_rule_s_acti_1e685d20' => 'Sind ALLE Bedingungen erfüllt, führt Radar die Aktion dieser Regel aus und prüft keine nachfolgenden Regeln. Diese Regeln werden nach den Zulassungs- und Sperrlisten und vor den integrierten Regeln geprüft.',
    'where_cbox_id_sends_people_after_they_sign_out_of_this_3a65532f' => 'Das Ziel, zu dem Cbox ID Personen nach der Abmeldung von dieser App weiterleitet. Die von der App angeforderte URI muss hier exakt stehen, einschließlich eines abschließenden Schrägstrichs. Andernfalls bleibt die Person auf der Abmeldeseite von Cbox ID. Lassen Sie das Feld leer, wenn die App keine Rückleitung anfordert.',
    'where_you_are_signed_in_what_can_act_as_you_and_what_ha_874bdb24' => 'Wo Sie angemeldet sind, was in Ihrem Namen handeln darf und was mit Ihrem Konto geschehen ist. Wenn Sie etwas nicht wiedererkennen, melden Sie die betreffende Sitzung ab und ändern Sie Ihr Passwort.',
    'while_you_are_migrating_off_another_system_your_app_can_a0c796b9' => 'Während des Umstiegs von einem anderen System kann Ihre App den bisherigen Anmeldeendpunkt in ihrem Manifest neben den Rollen angeben. Er erscheint hier zur Genehmigung, bevor er verwendet wird.',
    'while_you_move_off_another_system_an_app_can_ask_for_th_c182528e' => 'Während des Umstiegs von einem anderen System kann eine App anfordern, E-Mail-Adresse und Passwort von Personen, die noch nicht in Cbox ID sind, an ihrem bisherigen Anmeldeendpunkt zu prüfen. Testen Sie den Endpunkt vor der Genehmigung. Akzeptierte Personen werden hier angelegt und nie wieder dorthin geschickt. Fällt der Endpunkt jedoch aus, können sich noch nicht umgestellte Personen nicht anmelden.',
    'without_roles_everyone_who_can_sign_in_gets_whatever_an_dc1418f9' => 'Ohne Rollen erhalten alle angemeldeten Personen die Rechte, die eine App gewöhnlichen Benutzern gibt. Mit Rollen legen Sie einmal fest, wer beispielsweise bearbeiten darf und wer zum Support gehört. Alle verbundenen Apps können diese Zuordnung berücksichtigen.',
    'write_one_to_allow_challenge_or_block_on_what_you_know_9a9a03a4' => 'Erstellen Sie eine Regel zum Zulassen, zusätzlichen Verifizieren oder Blockieren anhand Ihrer Kenntnisse über die Benutzer. Verlangen Sie etwa eine zusätzliche Prüfung bei Anmeldungen außerhalb Ihrer Tätigkeitsländer oder nehmen Sie Ihr Büronetz von den Regeln zur Anmeldehäufigkeit aus.',
    'you_act_as_this_person_in_their_session_with_their_acce_36ea7fac' => 'Sie handeln als diese Person, in ihrer Sitzung und mit ihren Zugriffsrechten. Der Zugriff ist auf 30 Minuten begrenzt und, soweit die Konsole dies durchsetzen kann, schreibgeschützt. Jede Anfrage wird unter Ihrem Namen protokolliert.',
    'you_lose_access_immediately_as_its_owner_you_can_only_l_d51a2272' => 'Sie verlieren den Zugriff sofort. Als Eigentümer können Sie erst austreten, wenn eine andere Person die Organisation besitzt. Übertragen Sie zuerst das Eigentum oder löschen Sie die Organisation in den Einstellungen.',
    'your_app_s_own_access_model_resource_types_like_documen_24105154' => 'Das eigene Zugriffsmodell Ihrer App: Ressourcentypen wie Dokumente und Ordner, Beziehungen wie Eigentümer, Bearbeiter und Betrachter sowie deren Vererbung. Wer einen Ordner ansehen darf, kann beispielsweise alle Dokumente darin lesen. Ihre App speichert, wer in welcher Beziehung zu welcher Ressource steht, und fragt bei jeder Anfrage: „Darf dieser Benutzer dieses Dokument bearbeiten?“. Das Schema bestimmt die Antwort.',
    'your_app_s_own_access_model_resource_types_the_relation_3dddc87d' => 'Das eigene Zugriffsmodell Ihrer App: Ressourcentypen, deren Beziehungen und die Vererbung dieser Beziehungen. Ihre App schreibt Tupel — wer in welcher Beziehung zu welcher Ressource steht — und prüft die Berechtigungen bei jeder Anfrage.',
    'your_app_sends_these_one_call_per_batch_of_events_each_42f272f6' => 'Ihre App sendet diese Ereignisse mit einem Aufruf pro Stapel. Jedes Ereignis nennt die Organisation, in der es aufgetreten ist. Die Ereignisse erscheinen beim Eingang hier und bei den Administratoren der jeweiligen Organisation.',
    'your_environment_s_default_brand_the_hosted_sign_in_s_l_aae9270b' => 'Das Standardbranding Ihrer Umgebung: Aussehen, Logo und Favicon der gehosteten Anmeldung sowie der angezeigte Name und Absender. Jede Organisation übernimmt es, sofern sie kein eigenes Branding festlegt.',
    'your_identity_provider_creates_updates_and_deactivates_2d9dc172' => 'Ihr Identitätsanbieter erstellt, aktualisiert und deaktiviert Personen hier automatisch über den Standard SCIM. Ein Ein- oder Austritt in Ihrem HR-System erreicht Ihre Apps innerhalb weniger Sekunden, ohne Ticket und ohne zurückbleibende Konten — gerade beim Austritt ist das entscheidend.',
    'your_own_sign_in_methods_and_active_sessions_a_passkey_2bf79cbb' => 'Ihre eigenen Anmeldemethoden und aktiven Sitzungen. Ein Passkey bietet den stärksten Schutz und ist am schnellsten: Ihr Gerät entsperrt ihn per Fingerabdruck oder Gesichtserkennung, und es gibt kein Passwort, das durch Phishing gestohlen werden könnte.',
    'your_receiver_keeps_the_same_secret_a_64_character_hex_c0d890ee' => 'Ihr Empfänger behält dasselbe Geheimnis. Aus einem hexadezimalen Geheimnis mit 64 Zeichen wird whsec_ gefolgt von der Base64-Kodierung dieser Zeichenfolge — "whsec_" + base64(secret). Ein Geheimnis, das bereits mit whsec_ beginnt, wird unverändert verwendet.',
    '_groups_part1_39d243e0' => '{
  "groups": [":part1"]
}',
    '_part1_things_worth_doing_roughly_in_this_order_each_on_b3e154c4' => ':part1 Aufgaben, die sich lohnen, ungefähr in dieser Reihenfolge. Jede wird automatisch abgehakt, sobald sie tatsächlich erledigt ist. Sie müssen nichts manuell als abgeschlossen markieren.',
    '_sub_the_person_s_id_org_the_organization_they_are_acti_2e2ddc7f' => '{
  "sub": "die ID der Person",
  "org": "die Organisation, für die sie handelt",
  "roles": [":part1"],
  "permissions": [:part2]
}',
    'an_api_key_organization_settings_api_keys_not_an_applic_916c023d' => 'Ein API-Schlüssel (Organisationseinstellungen › API-Schlüssel), kein Anwendungsschlüssel. Er wird verschlüsselt gespeichert und nicht erneut angezeigt. :part1',
    'how_people_sign_in_to_part1_these_start_as_your_environ_133e7090' => 'Die Anmeldeverfahren für :part1. Ausgangspunkt sind die Standardeinstellungen Ihrer Umgebung. Änderungen hier können die Regeln nur verschärfen.',
    'its_members_are_signed_out_and_all_part1_it_owns_stop_s_80b419eb' => 'Die Mitglieder werden abgemeldet, und alle zugehörigen :part1 stellen ab der nächsten Anfrage die Authentifizierung ein. Die Sperre können Sie hier wieder aufheben.',
    'its_part1_are_signed_out_and_all_part2_it_owns_stop_ser_c1a0c179' => 'Die zugehörigen :part1 werden abgemeldet, und alle zugehörigen :part2 stellen ab der nächsten Anfrage die Authentifizierung ein. Die Sperre können Sie hier wieder aufheben.',
    'its_part1_can_no_longer_sign_in_to_this_organization_an_9a6e499c' => 'Die zugehörigen :part1 können sich nicht mehr bei dieser Organisation anmelden. Apps, die diese Organisation zur Authentifizierung verwenden, können sie ebenfalls nicht mehr authentifizieren. Unterorganisationen werden nicht mitgesperrt. Sie können die Organisation hier wieder aktivieren.',
    'minutes_at_most_part1_empty_uses_the_deployment_s_part2_2c261db9' => 'Minuten, höchstens :part1. Ein leeres Feld verwendet den Standardwert :part2 dieser Installation. Eine Verkürzung beendet auch bereits laufende Sitzungen, die das neue Limit überschreiten.',
    'only_if_your_app_needs_more_from_part1_than_sign_in_doe_fc539001' => 'Nur erforderlich, wenn Ihre App von :part1 mehr als die Anmeldung benötigt. Trennen Sie die Werte durch Leerzeichen. Die für die Anmeldung benötigten Scopes werden immer angefordert.',
    'paste_the_whole_json_key_file_of_a_service_account_gran_6f4e93cd' => 'Fügen Sie die vollständige JSON-Schlüsseldatei eines Dienstkontos ein, dem für diesen Bucket die Rolle roles/storage.objectCreator erteilt wurde. Sie wird verschlüsselt gespeichert und nicht erneut angezeigt. :part1',
    'sandbox_environments_allow_localhost_urls_and_never_sen_299fef2d' => 'Sandbox-Umgebungen erlauben localhost-URLs und versenden keine echten E-Mails. Im Tarif dieses Projekts sind noch :part1 verfügbar.',
    'sign_in_to_one_of_your_apps_as_part1_to_see_what_they_s_1c96b645' => 'Melden Sie sich bei einer Ihrer Apps als :part1 an, um deren Ansicht zu sehen. Die App erfährt, dass Sie handeln. Das Audit-Protokoll der Organisation erfasst, wer wann und aus welchem Grund gehandelt hat.',
    'the_app_whose_declared_roles_and_permissions_tokens_for_f9092feb' => 'Die App, deren deklarierte Rollen und Berechtigungen in den Token für diese API enthalten sind. Es können nur Apps ausgewählt werden, die :part1 gehören.',
    'what_part1_s_sign_in_page_offers_providers_from_the_env_efc01f8e' => 'Die Optionen auf der Anmeldeseite von :part1. Anbieter werden von der Umgebung geerbt. Diese Organisation kann einen Anbieter deaktivieren oder durch einen eigenen ersetzen.',
    'when_an_agent_s_key_needs_approval_for_an_action_the_re_56c5e366' => 'Benötigt der Schlüssel eines Agenten eine Genehmigung für eine Aktion, erscheint die Anfrage hier und auf dem Telefon der Person, die den Schlüssel erstellt hat. Sie wartet bis zu :part1.',
    'which_ways_in_part1_offers_besides_a_password_and_how_l_37522a30' => 'Welche Anmeldewege :part1 neben einem Passwort anbietet und wie lange eine Anmeldung gültig bleibt. Diese Einstellungen gelten für alle Organisationen darin gleichermaßen.',
    '_part1_the_part2_claim_is_a_different_thing_it_is_what_c15748b6' => ':part1 Der Claim :part2 hat eine andere Bedeutung: Er gibt an, was die :part3 :part4 anfordern durfte, nicht, was diese :part5 tun darf.',
    '_part1_this_console_is_not_signed_in_to_with_them_admin_a3d216ed' => ':part1 Diese Konsole verwendet sie nicht zur Anmeldung: Administratoren melden sich über Cbox ID unter :part2 mit den dort angebotenen Anmeldemethoden an.',
    '_part1_tick_the_part2_part3_scope_when_you_register_the_ef0603eb' => ':part1 Wählen Sie bei der Registrierung der App den Scope :part2 :part3 aus. Das ID-Token enthält dann dieselben Rollennamen als Claim :part4 – den Namen, den Kubernetes, Grafana und Vault erwarten. Weitere Einträge sind nicht nötig.',
    '_part1_you_are_impersonating_part2_part3_for_support_ev_aaad4d39' => ':part1 Sie handeln zu Supportzwecken als :part2 :part3. Alle Ihre Aktionen werden protokolliert. :part4 :part5 :part6',
    'a_management_key_acts_in_its_own_environment_only_expor_d9ba3890' => 'Ein Verwaltungsschlüssel gilt nur in seiner eigenen Umgebung. Exportieren Sie die Blaupause dieser App (GET /apps/{id}/blueprint) und registrieren Sie sie mit dem Schlüssel der anderen Umgebung (POST /apps mit `blueprint`).',
    'a_management_key_for_one_agent_it_can_do_only_what_its_e35f0a5f' => 'Ein Verwaltungsschlüssel für einen Agenten. Er erlaubt nur die Aktionen, die seine Scopes zulassen. Die von Ihnen ausgewählten Aktionen warten auf Ihre Genehmigung – auf Ihrem Telefon oder unter :part1.',
    'a_page_on_part1_leave_empty_to_land_in_the_console_with_1e303bfc' => 'Eine Seite auf :part1. Lassen Sie das Feld leer, um die Konsole zu öffnen; :part2 wird dann in der Einladung genannt.',
    'a_part1_is_one_product_s_idp_it_holds_isolated_part2_pa_c2f6b974' => 'Ein :part1 ist der Identitätsanbieter eines Produkts. Er enthält getrennte :part2 :part3 – Produktion und Sandbox – jeweils mit eigenen Benutzern, Schlüsseln und Anmeldungen, und wird über einen eigenen Tarif abgerechnet.',
    'a_permission_is_what_a_part1_may_do_once_signed_in_what_d4afab64' => 'Eine Berechtigung legt fest, was eine :part1 nach der Anmeldung tun darf. Was eine :part2 anfordern darf, bestimmt ein Scope, den Sie bei der Registrierung unter :part3 :part4 festlegen.',
    'a_workspace_key_reaches_the_workspace_itself_projects_e_28317ec8' => 'Ein Arbeitsbereichsschlüssel hat Zugriff auf den Arbeitsbereich selbst – Projekte, Umgebungen, Team und Schlüssel –, jedoch nicht auf die Inhalte einer Umgebung. Erstellen Sie einen unter :part1 :part2 :part3 auf der obersten Plattformebene.',
    'access_tokens_for_this_app_name_part1_as_their_audience_0da966a0' => 'Zugriffstoken für diese App nennen :part1 als Zielgruppe :part2. Diese API sollte nur Token akzeptieren, die sie als Zielgruppe nennen.',
    'access_tokens_for_this_app_name_this_environment_s_issu_13b4d3ef' => 'Zugriffstoken für diese App nennen den Aussteller dieser Umgebung, :part1 :part2, als Zielgruppe. Das ändert sich, sobald die App einen Scope einer Ihrer registrierten APIs erhält.',
    'add_a_txt_record_at_part1_part2_with_the_value_below_th_455edc17' => 'Fügen Sie unter :part1 :part2 einen TXT-Eintrag mit dem folgenden Wert hinzu und klicken Sie anschließend auf „Überprüfen“. Es kann einige Minuten dauern, bis DNS-Änderungen wirksam werden.',
    'an_app_registers_its_catalog_over_the_sdk_part1_part2_y_384ea703' => 'Eine App registriert ihren Katalog über das SDK. :part1 :part2 Sie können die Rolle jetzt erstellen und ihre Berechtigungen zusammenstellen, sobald die Schlüssel vorliegen.',
    'applications_that_trust_this_environment_as_their_saml_0e2642cf' => 'Anwendungen, die dieser Umgebung als SAML-Identitätsanbieter vertrauen. Damit sich Personen mit einem bereits vorhandenen Konto eines anderen Anbieters anmelden können, verwenden Sie :part1 :part2.',
    'approvals_cover_the_management_api_s_actions_these_scop_3eade41d' => 'Genehmigungen gelten für die Aktionen der Verwaltungs-API. Diese Scopes werden von Endpunkten bedient, die noch keine Aktionen sind. Sie werden daher ohne Rückfrage ausgeführt: :part1 :part2.',
    'apps_send_people_to_sign_up_with_part1_and_ask_a_signed_e3725846' => 'Apps leiten Personen mit :part1 zur Registrierung weiter und fordern angemeldete Personen mit :part2 auf, eine Organisation zu erstellen. Beides ist nur verfügbar, solange diese Einstellung aktiviert ist.',
    'asked_exactly_as_your_app_asks_it_part1_through_every_i_42253b49' => 'Die Anfrage wird genau wie von Ihrer App gestellt (:part1), einschließlich aller im Schema definierten Vererbungen.',
    'auth_settings_differ' => ':count Einstellung weicht von Ihrer Umgebung ab.|:count Einstellungen weichen von Ihrer Umgebung ab.',
    'connect_once_at_the_platform_root_instead_of_once_per_e_fbee6c88' => 'Stellen Sie die Verbindung einmal auf der obersten Plattformebene her, statt einzeln für jede Umgebung. Mit Ihrer Anmeldung besteht Zugriff auf Ihren Arbeitsbereich, alle von Ihnen verwalteten Umgebungen darin und Ihr eigenes Konto. Ein Umgebungswerkzeug erhält das Argument :part1 :part2, die REST-API den Header :part3, um das Ziel festzulegen. Der Zugriff bleibt auf Ihre Rechte und Ihre Freigaben beschränkt. Jede kritische Aktion wartet auf Ihre Genehmigung auf Ihrem Gerät.',
    'each_new_account_creates_its_own_organization_and_owns_3528fda3' => 'Jedes neue Konto erstellt eine eigene Organisation und wird deren Eigentümer. Apps können angemeldete Personen auch mit :part1 :part2 auffordern, eine Organisation zu erstellen.',
    'each_organization_gives_them_one_part1_what_they_may_ad_69f922a2' => 'Jede Organisation weist der Person genau eine :part1 zu – sie bestimmt, was die Person dort verwalten darf – und beliebig viele :part2, die ihre Rechte innerhalb der Apps festlegen.',
    'environment_part1_created_add_part2_from_the_environmen_9b25a836' => 'Umgebung „:part1“ erstellt. Fügen Sie :part2 in den Domaineinstellungen der Umgebung hinzu, um die Domain per DNS zu bestätigen. Eine unbestätigte Domain kann nicht als Aussteller dienen.',
    'environments_nest_under_a_project_and_a_project_under_a_03ba63b6' => 'Umgebungen gehören zu einem Projekt, Projekte zu einem :part1 :part2 :part3. Dort sehen Sie den gesamten Bestand eines Arbeitsbereichs. Zwei Arten von Einträgen gehören nie zu einem Arbeitsbereich: :part4 ist die Umgebung, in der diese Installation selbst läuft und in der die Konten der Plattformbetreiber und Arbeitsbereichsmitglieder liegen. Eine :part5 :part6-Umgebung hat kein Projekt; sie wird daher nicht abgerechnet und ist keinem Arbeitsbereich zugänglich. Keiner dieser Fälle ist ein Fehler, der hier behoben werden muss. Auf dieser Seite lassen sich beide auch nicht neu zuordnen.',
    'every_way_people_sign_in_to_part1_whether_it_is_on_and_4dda4364' => 'Alle Anmeldewege für :part1, ihr Aktivierungsstatus und wo sie geändert werden. Organisationen können strengere Regeln festlegen – :part2 :part3.',
    'every_workspace_environment_and_operator_on_part1_a_sus_e4247a2d' => 'Alle Arbeitsbereiche, Umgebungen und Plattformbetreiber auf :part1. Eine Sperrung, eine neue Umgebung oder eine Änderung an den Plattformbetreibern wirkt sich hier auf alle aus.',
    'feature_flag_part1_created_it_is_off_for_everyone_until_32603be3' => 'Feature-Flag „:part1“ erstellt. Es ist für alle deaktiviert, bis eine der folgenden Regeln oder die Standardeinstellung es aktiviert.',
    'framework_3cf574caed49' => 'Die Scopes :value1 gehören zu einer registrierten API, deren Scopes dieser Client nicht erhalten darf. Ein organisationsgebundener Client kann Scopes der APIs seiner eigenen Organisation sowie die für Mandanten anforderbaren Scopes umgebungsgebundener APIs erhalten.',
    'framework_43fd205dea6a' => 'Der Scope [:key] gehört bereits zu einer anderen API in dieser Umgebung. Scope-Schlüssel sind pro Umgebung eindeutig, da Token-Anfragen einen Scope nur anhand seines Schlüssels benennen.',
    'framework_47867973811e' => 'Verzeichnissynchronisierung mit :provider fehlgeschlagen: :request wurde wegen zu vieler Anfragen begrenzt (HTTP :status). Anzahl der Versuche: :attempt.',
    'framework_5eb368b0fb37' => 'Workday: Die Berichts-URL muss die Webservice-Adresse des Berichts sein: …/ccx/service/customreport2/{tenant}/{owner}/{report}.',
    'framework_632573ec7b49' => 'Die App [:clientId] muss denselben Eigentümer haben wie die API, deren Zugriffsregeln sie durchsetzt. Eine Verknüpfung würde Rollen und Berechtigungen eines Eigentümers in die Token eines anderen übernehmen.',
    'framework_87da9891b0ad' => 'Verzeichnissynchronisierung mit :provider fehlgeschlagen: :request war nach :attempt Versuchen nicht verfügbar (HTTP :status).',
    'framework_98eb4683e38b' => 'Verzeichnissynchronisierung mit :provider fehlgeschlagen: :request ist fehlgeschlagen (HTTP :status): nicht gefunden. Prüfen Sie das Konto, die Subdomain oder die Berichtsadresse.',
    'framework_a934fd6a0c26' => '[:origin] verwendet http. Der Schlüssel und alle damit ausgeführten Aktionen würden daher unverschlüsselt über das Netzwerk übertragen. Verwenden Sie https oder während der Entwicklung einen Loopback-Host wie http://localhost:3000.',
    'framework_b63785ee57fb' => 'Verzeichnissynchronisierung mit :provider fehlgeschlagen: :request ist fehlgeschlagen (HTTP :status): Die Zugangsdaten berechtigen nicht zum Lesen von Mitarbeiterdaten.',
    'framework_e5ca82ab9dff' => 'Verzeichnissynchronisierung mit :provider fehlgeschlagen: :request ist fehlgeschlagen (HTTP :status): Die Zugangsdaten wurden abgelehnt.',
    'framework_fc1964a8e8c4' => 'Dies ist das letzte gültige Geheimnis des Clients [:clientId]. Ersetzen Sie es durch eine Rotation. Ein Widerruf würde verhindern, dass sich der Client authentifiziert.',
    'if_that_endpoint_is_part1_people_who_have_not_migrated_18fc0415' => 'Wenn dieser Endpunkt :part1 ist, können sich noch nicht migrierte Personen nicht anmelden. Bereits migrierte Personen sind davon nicht betroffen.',
    'in_the_order_people_see_them_turning_one_of_the_environ_390888a5' => 'In der Reihenfolge, in der sie angezeigt werden. Wenn Sie hier einen Anbieter der Umgebung deaktivieren, wird lediglich die Schaltfläche von dieser Seite entfernt. Die Anmeldung damit bleibt andernorts möglich. Soll Ihr Identitätsanbieter der einzige Anmeldeweg sein, schreiben Sie SSO unter :part1 :part2 vor.',
    'keys_start_with_it_so_a_key_found_in_a_log_names_this_a_8a69e3c2' => 'Schlüssel beginnen mit diesem Präfix, sodass ein Schlüssel in einem Protokoll dieser App zugeordnet werden kann: :part1 :part2. 2–16 Kleinbuchstaben oder Ziffern, gefolgt von :part3 oder :part4 :part5, innerhalb dieser Umgebung eindeutig. Ein gesetztes Präfix aktiviert Schlüssel. Wenn Sie es entfernen, können keine neuen Schlüssel erstellt werden; bestehende bleiben bis zu ihrem Widerruf gültig.',
    'list_feature_flags_with_their_targeting_and_evaluate_ev_92059a92' => 'Feature-Flags mit ihren Zielgruppenregeln auflisten und jedes Flag für einen Benutzer in einer Organisation auswerten. Diese Anfrage stellt das Backend einer App, wenn ihm kein Token vorliegt.',
    'list_the_directories_scim_google_workspace_microsoft_en_97350786' => 'Verzeichnisse (SCIM, Google Workspace, Microsoft Entra) auflisten, aus denen Personen synchronisiert werden, einschließlich ihrer Gruppen und Synchronisierungsfehler. Bearer-Tokens oder Zugangsdaten der Anbieter werden niemals ausgegeben.',
    'list_the_saml_and_oidc_connections_organizations_sign_i_8dbbb680' => 'SAML- und OIDC-Verbindungen auflisten, über die sich Organisationen anmelden, sowie E-Mail-Domains, die Personen dorthin weiterleiten. Zertifikate, Client-Geheimnisse oder Signaturschlüssel werden niemals ausgegeben.',
    'list_the_third_party_providers_people_can_connect_their_1cc25b9b' => 'Drittanbieter auflisten, mit denen Personen ihre Konten verbinden können, einschließlich der Apps, die zeitlich begrenzten Zugriff auf diese Tokens erhalten dürfen, und der verbundenen Personen. Client-Geheimnisse oder Tokens werden niemals ausgegeben.',
    'mint_a_one_time_admin_portal_link_that_lets_an_organiza_9371449a' => 'Einmalige Links zum Admin-Portal erstellen und widerrufen. Damit kann der IT-Administrator einer Organisation SSO, Domains oder die Verzeichnissynchronisierung ohne eigenes Konto einrichten. Ein neuer Link wird nur einmal angezeigt.',
    'no_roles_to_map_onto_yet_define_one_under_part1_part2_o_9b9aba76' => 'Es gibt noch keine Rollen für die Zuordnung. Definieren Sie eine unter :part1 :part2 oder lassen Sie eine App ihre eigenen Rollen deklarieren.',
    'nobody_in_this_organization_has_created_a_key_for_one_o_462fe672' => 'Noch hat niemand in dieser Organisation einen Schlüssel für eine ihrer Apps erstellt. Personen erstellen eigene Schlüssel unter Mein Konto für eine App, die API-Schlüssel für Mitglieder in ihren Einstellungen aktiviert hat: :part1.',
    'nobody_is_signed_in_to_an_app_as_one_of_its_people_star_a41ae388' => 'Niemand ist in einer App als eine dieser Personen angemeldet. Starten Sie eine solche Sitzung über die Seite einer Person unter :part1 :part2.',
    'only_the_console_can_give_an_app_part1_not_a_management_e9037160' => 'Nur die Konsole kann einer App :part1 gewähren – weder ein Verwaltungsschlüssel noch ein Agent in Ihrem Auftrag. Erteilen Sie die Freigabe in der Konsole auf der Seite „Scopes“ der App.',
    'only_what_you_can_do_in_part1_yourself_is_offered_if_yo_54637548' => 'Es werden nur Aktionen angeboten, die Sie selbst in :part1 ausführen dürfen. Verlieren Sie später eine Berechtigung, verliert der Schlüssel sie ebenfalls.',
    'puts_the_keys_of_the_feature_flags_that_are_on_for_the_70599dc3' => 'Fügt die Schlüssel der Feature-Flags, die für die Person in der Organisation ihrer Anmeldung aktiviert sind, als Claim `feature_flags` in das Zugriffstoken, das ID-Token und UserInfo ein.',
    'puts_the_person_s_roles_on_the_id_token_under_the_name_1df84dc6' => 'Fügt die ROLLEN der Person unter dem Namen `groups` in das ID-Token ein. Diesen Namen erwarten Kubernetes, Grafana, Vault und viele ältere SaaS-Anwendungen. In dieser Konsole gibt es kein Objekt namens Gruppe. Erstellen Sie eine Rolle mit dem von der App erwarteten Namen; sie wird dann dort ausgegeben.',
    'read_radar_s_mode_built_in_and_custom_rules_allow_and_d_3e27d38d' => 'Radars Modus, integrierte und benutzerdefinierte Regeln, Zulassungs- und Sperrlisten sowie die Entscheidungsübersicht lesen: warum eine Anmeldung oder Registrierung zugelassen, zusätzlich verifiziert oder blockiert wurde. IP- oder E-Mail-Adressen aus einer Entscheidung werden niemals ausgegeben.',
    'read_the_audit_events_your_app_sent_and_the_exports_mad_e424eabd' => 'Die von Ihrer App gesendeten Audit-Ereignisse und ihre Exporte lesen, die Ereigniskette einer Organisation verifizieren und die zugehörigen Schemas sowie Aufbewahrungsregeln lesen.',
    'read_the_authorization_schema_and_its_tuples_and_ask_ch_e5b3f66c' => 'Das Autorisierungsschema und seine Tupel lesen sowie Berechtigungs- und Listenabfragen ausführen, etwa „Darf dieser Benutzer dieses Dokument bearbeiten?“ oder „Welche Dokumente darf er sehen?“. Genau die Rechte, die das Backend einer App zur Zugriffskontrolle benötigt.',
    'replace_the_authorization_schema_the_resource_types_and_f57d294e' => 'Das Autorisierungsschema ersetzen: die Ressourcentypen und die Regeln für jede Beziehung. Ändert unmittelbar das Ergebnis aller Berechtigungsprüfungen in dieser Umgebung.',
    'roles_held_across_the_whole_environment_in_every_organi_eb64cef7' => 'Rollen, die in der gesamten Umgebung gelten – in jeder Organisation und auch ohne Organisationszugehörigkeit. Organisationen können diese Rollen nie sehen. :part1 :part2',
    'sandbox_environment_for_testing_only_this_is_part1_your_4efdd306' => 'Sandbox-Umgebung – nur für Tests. Dies ist :part1 Ihre Produktionsanmeldung, und es werden keine echten E-Mails versendet.',
    'scope_part1_removed_apps_that_held_it_keep_it_as_a_type_7572a80d' => 'Scope „:part1“ entfernt. Apps, die ihn hatten, behalten ihn als frei eingegebenen Scope, der keinen Zugriff mehr auf diese API gewährt.',
    'showing_the_first_part1_search_to_reach_the_rest_anythi_57d8cba9' => 'Die ersten :part1 werden angezeigt. Suchen Sie nach den übrigen Einträgen. Bereits ausgewählte Einträge bleiben in der Liste.',
    'sms_allowed_country_count' => 'In :count Land als zweiter Faktor zugelassen.|In :count Ländern als zweiter Faktor zugelassen.',
    'someone_who_part1_is_never_sent_their_password_is_the_o_6e557319' => 'Die Daten einer Person, die :part1, werden nie übermittelt. Ihr Passwort ist das in Cbox ID; das alte System hat darauf keinen Einfluss.',
    'someone_who_signs_in_and_is_part1_has_their_email_and_p_07a25128' => 'Wenn sich eine Person anmeldet und :part1 ist, werden ihre E-Mail-Adresse und ihr Passwort an diesen Endpunkt gesendet. Bei einer Bestätigung wird sie hier angelegt; ihre Daten werden danach nicht mehr dorthin gesendet.',
    'store_rotate_and_revoke_downstream_credentials_and_gran_86bf996c' => 'Zugangsdaten für nachgelagerte Dienste speichern, rotieren und widerrufen sowie einer App zeitlich begrenzten Zugriff darauf gewähren oder entziehen. Dies betrifft nicht die Berechtigungsbereiche vault.manage / vault.lease im eigenen Token einer App.',
    'streamable_http_every_request_carries_part1_part2_a_man_6348600d' => 'Streamable HTTP. Jede Anfrage enthält :part1 :part2 – einen Verwaltungsschlüssel dieser Umgebung.',
    'stuck_on_one_of_these_every_page_in_the_console_has_a_p_2aa4622e' => 'Kommen Sie bei einem dieser Punkte nicht weiter? Jede Seite der Konsole hat neben ihrem Titel ein :part1 :part2 :part3 mit einer kurzen Erklärung und einem Link zur vollständigen Anleitung.',
    'suspension_is_the_only_lever_here_and_it_is_reversible_84455a59' => 'Hier können Sie einen Arbeitsbereich ausschließlich sperren oder die Sperre aufheben. Nichts auf dieser Seite löscht einen Arbeitsbereich oder entfernt seine Daten endgültig. Eine Installation enthält außerdem Umgebungen ohne zugehörigen Arbeitsbereich: die Plattformwurzel und unzugeordnete Restbestände. Beide sind unter :part1 :part2 entsprechend gekennzeichnet.',
    'suspension_is_the_only_thing_this_page_changes_and_it_i_4b1a3610' => 'Diese Seite ändert ausschließlich die Sperrung, die sich jederzeit aufheben lässt. Das Auswählen und Öffnen einer Umgebung wechselt nur die Ansicht der Konsole. Die beteiligten Umgebungen werden dabei nicht verändert.',
    'text_message_codes_to_part1_stop_working_their_authenti_81d0cd27' => 'SMS-Codes an :part1 funktionieren nicht mehr. Authenticator-App, Passkeys und Wiederherstellungscodes bleiben unverändert. War die Telefonnummer der einzige zweite Faktor, ist das Konto bis zur erneuten Einrichtung allein durch sein Passwort geschützt.',
    'that_certificate_has_already_expired_part1_download_the_9adb4bed' => 'Dieses Zertifikat ist bereits abgelaufen (:part1). Laden Sie das aktuelle Zertifikat von Ihrem Identitätsanbieter herunter.',
    'that_favicon_cannot_be_used_send_the_image_itself_as_a_96450fb1' => 'Dieses Favicon kann nicht verwendet werden. Senden Sie das Bild selbst als Base64-data:-URI (data:image/png;base64,…). Externe Bild-URLs werden nicht akzeptiert: Jeder Besucher lädt das Bild der Anmeldeseite, sodass dessen externer Anbieter Informationen über die Besucher erhielte.',
    'that_is_a_lot_of_emails_try_again_in_part1_seconds_or_c_1e69af47' => 'Es wurden viele E-Mails angefordert. Versuchen Sie es in :part1 Sekunden erneut oder prüfen Sie inzwischen Ihren Spam-Ordner.',
    'that_is_everything_on_the_list_from_here_the_console_is_d3be406f' => 'Damit sind alle Punkte der Liste erledigt. Künftig werden Sie die Konsole vor allem bei Bedarf wieder öffnen. Zwei Bereiche sollten Sie regelmäßig prüfen: :part1 :part2 :part3 und :part4 :part5 :part6.',
    'that_logo_cannot_be_used_send_the_image_itself_as_a_bas_ae6a22d5' => 'Dieses Logo kann nicht verwendet werden. Senden Sie das Bild selbst als Base64-data:-URI (data:image/png;base64,…). Externe Bild-URLs werden nicht akzeptiert: Jeder Besucher lädt das Bild der Anmeldeseite, sodass dessen externer Anbieter Informationen über die Besucher erhielte.',
    'the_email_domains_your_organizations_have_claimed_a_ver_97773852' => 'Die E-Mail-Domains, deren Inhaberschaft Ihre Organisationen beanspruchen. Eine verifizierte Domain leitet alle Personen mit einer zugehörigen Adresse zur Verbindung der Organisation weiter: :part1 :part2. Jede Domain wird auf der Seite ihrer Organisation verifiziert.',
    'the_platform_s_own_environment_on_part1_how_every_works_07c8a7ac' => 'Die eigene Umgebung der Plattform unter :part1: Hier melden sich alle Arbeitsbereichseigentümer und Plattformbetreiber bei Cbox ID an, ebenso erfolgt hier die Anmeldung an allen Umgebungskonsolen. Änderungen gelten für alle diese Anmeldungen.',
    'the_role_part1_cannot_be_held_in_this_organization_it_b_6fdeacd4' => 'Die Rolle [:part1] kann in dieser Organisation nicht zugewiesen werden. Sie gehört zu einer anderen Organisation oder zu einer App, die diese Organisation nicht nutzen darf.',
    'there_is_no_client_secret_to_paste_part1_expects_a_sign_574fe375' => 'Es muss kein Client-Geheimnis eingefügt werden. :part1 erwartet stattdessen eine signierte Assertion, die wir für jede Anmeldung mit dem obigen Schlüssel erzeugen und lange vor ihrem Ablauf erneuern.',
    'there_is_no_role_to_grant_yet_define_one_on_the_part1_p_ffe056a6' => 'Es gibt noch keine Rolle, die zugewiesen werden kann. Definieren Sie eine auf der Seite :part1 :part2 :part3 oder lassen Sie eine App ihre eigenen Rollen im Manifest deklarieren.',
    'these_are_the_buttons_on_part1_how_every_workspace_owne_5c0655c0' => 'Dies sind die Schaltflächen auf :part1, über die sich Arbeitsbereichseigentümer und Plattformbetreiber bei Cbox ID und damit an den Konsolen aller Umgebungen anmelden. Deren Administratoren verwenden Cbox-ID-Konten. Hinterlegen Sie beim jeweiligen Anbieter die angezeigte Weiterleitungs-URI. Sie finden sie unter :part2 :part3.',
    'these_buttons_are_for_the_people_who_sign_in_to_your_ap_580f5efd' => 'Diese Schaltflächen sind für Personen bestimmt, die sich bei Ihren Apps anmelden, auf den Anmeldeseiten von :part1 :part2. :part3',
    'they_become_the_owner_of_part1_and_you_become_an_admin_09c4a8dc' => 'Die Person wird Eigentümer von :part1, und Sie werden Administrator. Nur der neue Eigentümer kann das Eigentum zurückübertragen.',
    'this_app_holds_scopes_of_more_than_one_api_part1_part2_163d032f' => 'Diese App hat Berechtigungsbereiche für mehrere APIs: :part1 :part2. Ein Token gilt jeweils für eine API. Die App gibt daher mit dem Parameter :part3 an, welche API sie benötigt. Eine Anfrage nach Berechtigungsbereichen zweier APIs gleichzeitig wird abgelehnt.',
    'this_console_is_your_workspace_its_projects_team_keys_a_66180b31' => 'Diese Konsole ist Ihr Arbeitsbereich mit Projekten, Team, Schlüsseln und Abrechnung. Wie sich Personen bei Ihren Apps anmelden, einschließlich :part1, wird je Umgebung in deren eigener Konsole eingerichtet.',
    'this_credential_needs_a_person_s_approval_for_this_acti_6e7eed81' => 'Für diese Aktion benötigt dieses Zugangsmittel die Genehmigung einer Person. Es ist jedoch keine Person hinterlegt, die sie erteilen kann. Führen Sie die Aktion in der Konsole aus oder erstellen Sie dort einen Schlüssel, dessen Eigentümer die Genehmigung erteilen kann.',
    'this_deployment_only_texts_part1_so_numbers_in_part2_ca_6cb21f4d' => 'Diese Installation versendet SMS nur nach :part1. Nummern in :part2 können daher erst Codes empfangen, wenn sie in CBOX_ID_SMS_ALLOWED_COUNTRIES enthalten sind.',
    'this_environment_s_issuer_discovery_and_jwks_are_served_06e9c844' => 'Aussteller, Discovery und JWKS dieser Umgebung werden unter :part1 :part2 bereitgestellt. Richten Sie den Host auf Ihren Ingress und terminieren Sie TLS dort.',
    'this_environment_s_own_issuer_what_an_sdk_discovers_fro_b00e706b' => 'Der eigene Aussteller dieser Umgebung – die Adresse für die Discovery durch ein SDK und der Wert des Claims :part1.',
    'this_person_is_the_only_owner_of_part1_organization_s_p_662dfa99' => 'Diese Person ist der einzige Eigentümer von :part1 Organisation(en): :part2. Übertragen Sie das Eigentum, bevor Sie die Person löschen.',
    'typed_scopes_part1_are_unowned_they_travel_as_they_are_e061e25f' => 'Frei eingegebene Scopes (:part1) haben keinen Eigentümer. Sie werden unverändert übermittelt und nie mit einer registrierten API als Zielgruppe.',
    'we_could_not_send_the_email_right_now_this_deployment_c_03e046b9' => 'Die E-Mail konnte momentan nicht gesendet werden, weil diese Installation ihren Mailserver nicht erreicht. Versuchen Sie es später erneut. Ein Administrator kann Ihre Adresse auch mit `php artisan cbox-id:users:confirm-email` bestätigen.',
    'we_have_sent_a_few_links_already_try_again_in_part1_sec_a84fe552' => 'Wir haben bereits mehrere Links versendet. Versuchen Sie es in :part1 Sekunden erneut oder prüfen Sie inzwischen Ihren Spam-Ordner.',
    'we_sent_a_link_to_part1_your_first_environment_your_liv_9786541d' => 'Wir haben einen Link an :part1 gesendet. Sobald Sie ihn öffnen, wird Ihre erste Umgebung erstellt: Ihr produktiver Identitätsanbieter mit eigener Anmeldung, Benutzern und Signaturschlüsseln. Anschließend gelangen Sie direkt hierher zurück. Der Link ist 24 Stunden gültig.',
    'which_of_its_actions_wait_for_a_person_the_agent_gets_a_e72df5dd' => 'Die Aktionen, die auf eine Genehmigung warten. Der Agent erhält eine 202-Antwort mit einem kurzen Code. Sie genehmigen die Aktion auf Ihrem Telefon oder unter :part1 :part2. Anschließend wiederholt der Agent die Anfrage genau einmal.',
    'write_and_delete_relationship_tuples_who_owns_edits_or_53581cba' => 'Beziehungstupel schreiben und löschen: wem die Ressourcen Ihrer App gehören und wer sie bearbeiten oder ansehen darf. Der Zugriff in Ihrer App wird unmittelbar mit der Änderung erteilt oder entzogen.',
